import type { LexicalEditor } from "lexical";

import { HTML_EXAMPLE, MARKDOWN_EXAMPLE } from "./constants";
import {
  createEmptyEditorState,
  loadMarkdownContent,
  replaceEditorHtmlContent,
} from "./utils";

export const copyEditorOutput = async (value: string) => {
  await navigator.clipboard.writeText(value);
};

/**
 * Triggers a browser download of the given markdown as a `.md` file, reusing
 * the same serialized markdown the output panel already exposes.
 */
export const downloadMarkdownContent = (
  content: string,
  filename = "document.md"
) => {
  const blob = new Blob([content], { type: "text/markdown;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");

  link.href = url;
  link.download = filename.endsWith(".md") ? filename : `${filename}.md`;
  document.body.append(link);
  link.click();
  link.remove();
  URL.revokeObjectURL(url);
};

export const resetEditorContent = (editor: LexicalEditor) => {
  createEmptyEditorState(editor);
};

export const loadEditorHtmlExample = (editor: LexicalEditor) => {
  replaceEditorHtmlContent(editor, HTML_EXAMPLE);
};

export const loadEditorMarkdownExample = (editor: LexicalEditor) => {
  loadMarkdownContent(editor, MARKDOWN_EXAMPLE);
};

/** Shape of a single color entry in the palette. */
export interface ColorSwatch {
  /** Human-readable label (used as aria-label on the swatch button). */
  label: string;
  /** CSS color value, e.g. "#ef4444". */
  value: string;
}

/**
 * Default color palette shared by the text color and background color pickers.
 *
 * To customise the available swatches, edit this array — the order determines
 * the rendering order in the grid. Both pickers import this constant as their
 * default, but each `<ColorSwatches>` instance also accepts a custom `palette`
 * prop if you need diverging sets.
 */
export const COLOR_PALETTE: ColorSwatch[] = [
  { label: "Black", value: "#1a1a1a" },
  { label: "Dark gray", value: "#525252" },
  { label: "Gray", value: "#a3a3a3" },
  { label: "White", value: "#ffffff" },
  { label: "Red", value: "#ef4444" },
  { label: "Orange", value: "#f97316" },
  { label: "Yellow", value: "#eab308" },
  { label: "Green", value: "#22c55e" },
  { label: "Cyan", value: "#06b6d4" },
  { label: "Blue", value: "#3b82f6" },
  { label: "Violet", value: "#8b5cf6" },
  { label: "Pink", value: "#ec4899" },
  { label: "Light red", value: "#fca5a5" },
  { label: "Light yellow", value: "#fde68a" },
  { label: "Light green", value: "#bbf7d0" },
  { label: "Light blue", value: "#bfdbfe" },
];

import type { ReactNode } from "react";

import type {
  EditorChromeOptions,
  EditorFeatureFlags,
  EditorSnapshotOptions,
} from "./types";

export const DEFAULT_EDITOR_SNAPSHOT_OPTIONS = {
  emitInitialSnapshot: true,
  html: true,
  markdown: true,
  text: true,
} as const satisfies Required<EditorSnapshotOptions>;

export type ResolvedEditorSnapshotOptions = Required<EditorSnapshotOptions>;

export const resolveEditorSnapshotOptions = (
  options?: EditorSnapshotOptions
): ResolvedEditorSnapshotOptions => ({
  ...DEFAULT_EDITOR_SNAPSHOT_OPTIONS,
  ...options,
});

export type ResolvedEditorFeatureFlags = Required<
  Omit<EditorFeatureFlags, "snapshot">
> & {
  snapshot: ResolvedEditorSnapshotOptions;
};
export type ResolvedEditorChromeOptions = Required<EditorChromeOptions>;

export const DEFAULT_EDITOR_FEATURES = {
  exportMarkdown: true,
  floatingLinkEditor: true,
  floatingToolbar: true,
  focusOnMount: true,
  history: true,
  markdownShortcuts: true,
  slashCommand: true,
  snapshot: DEFAULT_EDITOR_SNAPSHOT_OPTIONS,
  tabIndentation: true,
} as const satisfies ResolvedEditorFeatureFlags;

export const DEFAULT_EDITOR_CHROME = {
  actionBar: true,
  footer: true,
  header: true,
  outputs: true,
  shell: true,
} as const satisfies Required<EditorChromeOptions>;

export const resolveEditorFeatures = (
  features?: EditorFeatureFlags
): ResolvedEditorFeatureFlags => {
  const { snapshot, ...flags } = features ?? {};

  return {
    ...DEFAULT_EDITOR_FEATURES,
    ...flags,
    // The nested snapshot bag is resolved separately so a partial override
    // (e.g. `{ html: false }`) never loses the sibling defaults.
    snapshot: resolveEditorSnapshotOptions(snapshot),
  };
};

export const resolveEditorChrome = (
  chrome?: EditorChromeOptions
): ResolvedEditorChromeOptions => ({
  ...DEFAULT_EDITOR_CHROME,
  ...chrome,
});

export const renderEditorSlot = <T>(
  slot: ReactNode | ((context: T) => ReactNode) | undefined,
  context: T
): ReactNode | undefined => {
  if (typeof slot === "function") {
    return slot(context);
  }

  return slot;
};

export const shouldRenderEditorShell = ({
  chromeShell,
  minimal,
  shellSlot,
}: {
  chromeShell: boolean;
  minimal: boolean;
  shellSlot:
    | ReactNode
    | ((context: { children: ReactNode }) => ReactNode)
    | undefined;
}) => {
  if (shellSlot !== undefined) {
    return true;
  }

  if (minimal) {
    return false;
  }

  return chromeShell;
};

import { CodeHighlightNode, CodeNode } from "@lexical/code";
import { HorizontalRuleNode } from "@lexical/extension";
import { AutoLinkNode, LinkNode } from "@lexical/link";
import { ListItemNode, ListNode } from "@lexical/list";
import type { InitialConfigType } from "@lexical/react/LexicalComposer";
import { HeadingNode, QuoteNode } from "@lexical/rich-text";
import { TableCellNode, TableNode, TableRowNode } from "@lexical/table";

import type { LexicalNodeList } from "./features";
import { editorTheme } from "./theme";

function onError(error: Error) {
  console.error("[Editor]", error);
}

/**
 * Lexical nodes that are always registered regardless of feature toggles.
 * Feature-owned nodes (image, youtube, math, collapsible, layout) are resolved
 * separately from the feature registry and appended through `featureNodes`.
 */
export const BASE_EDITOR_NODES = [
  HeadingNode,
  QuoteNode,
  ListNode,
  ListItemNode,
  CodeNode,
  CodeHighlightNode,
  LinkNode,
  AutoLinkNode,
  HorizontalRuleNode,
  TableNode,
  TableRowNode,
  TableCellNode,
];

interface CreateEditorConfigOptions {
  editable: boolean;
  /**
   * Initial-state builder run by LexicalComposer inside the very first
   * update, before any plugin mounts. Used to seed content synchronously
   * so the editor's first paint already contains the document.
   */
  editorState?: InitialConfigType["editorState"];
  /** Consumer-provided nodes appended after everything else. */
  extraNodes?: NonNullable<InitialConfigType["nodes"]>;
  /** Nodes contributed by enabled feature descriptors. */
  featureNodes?: LexicalNodeList;
  namespace?: string;
}

export const createEditorConfig = ({
  editable,
  editorState,
  namespace = "PytahEditor",
  featureNodes = [],
  extraNodes,
}: CreateEditorConfigOptions): InitialConfigType => {
  const nodes = [...BASE_EDITOR_NODES, ...featureNodes, ...(extraNodes ?? [])];

  return {
    editable,
    namespace,
    nodes,
    onError,
    theme: editorTheme,
    ...(editorState ? { editorState } : {}),
  };
};

import { createContext, useContext } from "react";

/**
 * Slash command ids resolved from the enabled feature set (core plus
 * installed extras). Shared chrome (dropdowns, insert menus) reads this to
 * feature-gate its options without any static import from feature folders.
 */
export const EditorResolvedCommandsContext = createContext<readonly string[]>(
  []
);

export const useEditorResolvedCommands = (): readonly string[] =>
  useContext(EditorResolvedCommandsContext);

import type { Transformer } from "@lexical/markdown";
import { createContext, useContext } from "react";

export const EditorTransformersContext = createContext<readonly Transformer[]>(
  []
);

export const useEditorTransformers = (): readonly Transformer[] =>
  useContext(EditorTransformersContext);

"use client";

import type { Transformer } from "@lexical/markdown";
import type { InitialConfigType } from "@lexical/react/LexicalComposer";
import type { ComponentType } from "react";

import { FocusOnMountPlugin } from "../plugins/core/focus-on-mount";
import { MarkdownExportPlugin } from "../plugins/export-markdown/plugin";
import { FloatingToolbarPlugin } from "../plugins/floating-toolbar/plugin";
import { FloatingLinkEditorPlugin } from "../plugins/link-behavior/floating-link-editor";
import { BUILTIN_MARKDOWN_TRANSFORMERS } from "../plugins/markdown/transformers";
import { CORE_SLASH_COMMANDS } from "../plugins/slash-command/commands";
import { CORE_SLASH_COMMAND_EXECUTORS } from "../plugins/slash-command/executors";
import { SlashCommandPlugin } from "../plugins/slash-command/plugin";
import type {
  FeatureSlashCommand,
  SlashCommand,
} from "../plugins/slash-command/types";
import { replaceCurrentBlock } from "../plugins/slash-command/utils";
import type { EditorFeatureFlags, ExtraEditorFeature } from "./types";

export type ComputedNode = NonNullable<InitialConfigType["nodes"]>[number];

export type LexicalNodeList = ComputedNode[];

/**
 * One descriptor of a built-in *core* capability — behavior the base editor
 * always ships and consumers can toggle at runtime through
 * `EditorFeatureFlags`. Content features (images, tables, drawings, ...) are
 * not listed here: they ship as separate registry items and are composed via
 * `extraFeatures`, so uninstalled features never reach the bundle.
 */
export interface EditorFeature {
  /** Only mount the plugin when the editor is editable. */
  editableOnly?: boolean;
  /** Whether the feature can be toggled by name inside `EditorFeatureFlags`. */
  flag: keyof EditorFeatureFlags & string;
  /** The behavior plugin to mount on the editor. */
  plugin?: ComponentType;
}

/**
 * The ordered list of built-in core features. Nodes, transformers and slash
 * commands for removable content features live beside their features
 * (`plugins/<feature>/feature.ts`) and are wired through `extraFeatures`.
 */
export const EDITOR_FEATURES: readonly EditorFeature[] = [
  {
    editableOnly: true,
    flag: "focusOnMount",
    plugin: FocusOnMountPlugin,
  },
  {
    editableOnly: true,
    flag: "floatingLinkEditor",
    plugin: FloatingLinkEditorPlugin,
  },
  {
    editableOnly: true,
    flag: "floatingToolbar",
    plugin: FloatingToolbarPlugin,
  },
  {
    flag: "exportMarkdown",
    plugin: MarkdownExportPlugin,
  },
];

/**
 * Collects node registrations contributed by installed extras. Core nodes
 * (headings, lists, links, code, base table) are registered statically in
 * `core/config.ts` and are not affected.
 */
export const computeFeatureNodes = (
  extraFeatures?: readonly ExtraEditorFeature[]
): LexicalNodeList => {
  const nodes: LexicalNodeList = [];

  for (const extra of extraFeatures ?? []) {
    if (extra.nodes) {
      nodes.push(...extra.nodes);
    }
  }

  return nodes;
};

/**
 * Core transformer set plus every transformer contributed by installed
 * extras — this is what markdown shortcuts, seeding and snapshot reads use.
 */
export const computeEditorTransformers = (
  extraFeatures?: readonly ExtraEditorFeature[]
): readonly Transformer[] => {
  const transformers: Transformer[] = [...BUILTIN_MARKDOWN_TRANSFORMERS];

  for (const extra of extraFeatures ?? []) {
    if (extra.transformers) {
      transformers.push(...extra.transformers);
    }
  }

  return transformers;
};

const buildCoreSlashCommandEntry = (
  command: SlashCommand
): FeatureSlashCommand => ({
  command,
  run: (editor) => {
    const executor = CORE_SLASH_COMMAND_EXECUTORS[command.id];
    if (!executor) {
      return;
    }
    replaceCurrentBlock(editor, executor);
  },
});

/**
 * Core block-type commands are always available; feature-scoped entries come
 * exclusively from installed extras. The shared insert menu renders exactly
 * this resolved list.
 */
export const computeResolvedSlashCommands = (
  extraFeatures?: readonly ExtraEditorFeature[]
): readonly FeatureSlashCommand[] => {
  const commands: FeatureSlashCommand[] = CORE_SLASH_COMMANDS.map(
    buildCoreSlashCommandEntry
  );

  for (const extra of extraFeatures ?? []) {
    if (extra.slashCommands) {
      commands.push(...extra.slashCommands);
    }
  }

  return commands;
};

/**
 * Mounted by the composition surface when the `slashCommand` flag is enabled.
 * Receives the fully resolved contribution list rather than raw ids.
 */
export const renderSlashCommandPlugin = (
  commands: readonly FeatureSlashCommand[]
) => <SlashCommandPlugin commands={commands} />;

/* ==========================================================================
 * Editor design tokens (v1)
 *
 * Single source of truth for fast editor restyling. Consumers override
 * `--editor-*` custom properties — no scattered Tailwind literal hunting.
 *
 * Token kinds (see AGENTS.md token table — aliases vs. owned):
 * - `alias`: `var(--shadcn-token, <oklch fallback>)` — follows the shadcn
 *   theme automatically (light/dark via `:root`/`.dark` in `src/index.css`).
 *   Every alias carries an explicit fallback so a `shadcn update` that
 *   renames base tokens degrades to a pinned value instead of `unset`.
 * - `owned`: editor-specific value (spacing, type scale, radii, shadows).
 *   Light default lives in `:root`; dark deltas (if any) live in `.dark`.
 *
 * Density presets: `:root` whims are `comfortable` (Notion-like). Setting
 * `data-density="compact"` (via the `density` prop on `Editor`) overrides
 * the spacing/line-height subset below — Linear-like density.
 *
 * v1 scope: canvas content + toolbar + chrome + floating surfaces + table +
 * image. v1.1 tokenized the rest: code container, collapsible, layout
 * (+ preset picker), math, youtube, link panel, table menu width.
 * The `codeHighlight` Prism palette stays literal by design (swap the whole
 * map for another syntax theme); slash/TOC popovers and the Excalidraw
 * preview keep custom variants.
 * ========================================================================== */

:root {
  /* --- Canvas content (owned, comfortable defaults = current visuals) --- */
  --editor-content-max-w: none;
  --editor-content-px: 2rem; /* px-8 */
  --editor-content-py: 2.5rem; /* py-10 */
  --editor-content-min-h: 26.25rem; /* min-h-105 */
  --editor-content-font-size: 17px; /* text-content */
  --editor-content-line-height: 2rem; /* leading-8 */
  --editor-content-bg: var(--background, oklch(1 0 0)); /* alias */
  --editor-block-gap: 0.25rem; /* paragraph mb-1 */
  --editor-paragraph-line-height: 1.75rem; /* paragraph leading-7 */

  /* --- Type scale (owned — mirrors current theme.ts) --- */
  --editor-h1-size: 2.25rem;
  --editor-h1-mt: 3rem;
  --editor-h1-mb: 1.25rem;
  --editor-h2-size: 1.875rem;
  --editor-h2-mt: 2.5rem;
  --editor-h2-mb: 1rem;
  --editor-h3-size: 1.5rem;
  --editor-h3-mt: 2rem;
  --editor-h3-mb: 0.75rem;
  --editor-h4-size: 1.25rem;
  --editor-h4-mt: 1.5rem;
  --editor-h4-mb: 0.5rem;
  --editor-h5-size: 1.125rem;
  --editor-h5-mt: 1.25rem;
  --editor-h5-mb: 0.5rem;
  --editor-h6-size: 1.0625rem;
  --editor-h6-mt: 1rem;
  --editor-h6-mb: 0.5rem;
  --editor-quote-border: color-mix(
    in oklch,
    var(--foreground, oklch(0.145 0 0)) 20%,
    transparent
  );
  --editor-list-indent: 1.5rem; /* ml-6 */
  --editor-list-gap: 0.5rem; /* mb-2 */
  --editor-list-item-gap: 0.125rem; /* mb-0.5 */

  /* --- Toolbar (owned) --- */
  --editor-toolbar-px: 2rem; /* aligns with content px */
  --editor-toolbar-py: 0.5rem; /* py-2 */

  /* --- Chrome shell/header/footer/action-bar --- */
  --editor-shell-bg: color-mix(
    in oklch,
    var(--background, oklch(1 0 0)) 95%,
    transparent
  ); /* alias-tinted */
  --editor-shell-border: var(--border, oklch(0.922 0 0)); /* alias */
  --editor-shell-radius: var(--radius-md, 0.5rem); /* capped at rounded-md */
  --editor-header-bg: color-mix(
    in oklch,
    var(--muted, oklch(0.97 0 0)) 40%,
    transparent
  ); /* alias-tinted */
  --editor-footer-bg: color-mix(
    in oklch,
    var(--muted, oklch(0.97 0 0)) 30%,
    transparent
  ); /* alias-tinted */
  --editor-actionbar-bg: color-mix(
    in oklch,
    var(--muted, oklch(0.97 0 0)) 20%,
    transparent
  ); /* alias-tinted */
  --editor-chrome-px: 1rem; /* px-4 */
  --editor-chrome-py: 0.75rem; /* py-3 */
  --editor-chrome-py-sm: 0.5rem; /* py-2 */

  /* --- Floating surfaces (canonical: toolbar + excalidraw confirm) --- */
  --editor-floating-bg: var(--popover, oklch(1 0 0)); /* alias */
  --editor-floating-foreground: var(
    --popover-foreground,
    oklch(0.145 0 0)
  ); /* alias */
  --editor-floating-ring: var(--border, oklch(0.922 0 0)); /* alias */
  --editor-floating-radius: var(--radius-md, 0.5rem); /* capped at rounded-md */
  --editor-floating-shadow:
    0 10px 15px -3px rgb(0 0 0 / 0.1), 0 4px 6px -4px rgb(0 0 0 / 0.1); /* shadow-lg, owned */
  --editor-floating-padding-sm: 0.375rem; /* p-1.5 */
  --editor-floating-padding-md: 0.5rem; /* p-2 */
  --editor-floating-padding-lg: 1rem; /* p-4 */

  /* --- Tables (owned geometry + alias colors) --- */
  --editor-table-gap-y: 1rem; /* my-4 */
  --editor-table-radius: var(--radius-md, 0.5rem); /* rounded-md */
  --editor-table-border: var(--border, oklch(0.922 0 0)); /* alias */
  --editor-table-cell-px: 0.75rem; /* px-3 */
  --editor-table-cell-py: 0.5rem; /* py-2 */
  --editor-table-cell-min-w: 8rem; /* min-w-32 */
  --editor-table-header-bg: color-mix(
    in oklch,
    var(--muted, oklch(0.97 0 0)) 60%,
    transparent
  ); /* alias-tinted */
  --editor-table-striped-bg: color-mix(
    in oklch,
    var(--muted, oklch(0.97 0 0)) 10%,
    transparent
  ); /* alias-tinted */
  --editor-table-selected-border: var(--primary, oklch(0.205 0 0)); /* alias */
  --editor-table-selected-bg: color-mix(
    in oklch,
    var(--primary, oklch(0.205 0 0)) 10%,
    transparent
  ); /* alias-tinted */
  --editor-table-menu-w: 14rem; /* w-56 */

  /* --- Images (owned geometry + alias colors) --- */
  --editor-image-gap-y: 1rem; /* my-4 */
  --editor-image-radius: var(--radius-md, 0.5rem); /* capped at rounded-md */
  --editor-image-frame-radius: var(
    --radius-md,
    0.5rem
  ); /* capped at rounded-md */
  --editor-image-border: color-mix(
    in oklch,
    var(--border, oklch(0.922 0 0)) 60%,
    transparent
  ); /* alias-tinted */
  --editor-image-bg: color-mix(
    in oklch,
    var(--muted, oklch(0.97 0 0)) 20%,
    transparent
  ); /* alias-tinted */
  --editor-image-selected-ring: color-mix(
    in oklch,
    var(--primary, oklch(0.205 0 0)) 40%,
    transparent
  ); /* alias-tinted */
  --editor-handle-size: 0.5rem; /* size-2 */
  --editor-handle-bg: var(--foreground, oklch(0.145 0 0)); /* alias */
  --editor-handle-border: color-mix(
    in oklch,
    var(--background, oklch(1 0 0)) 20%,
    transparent
  ); /* alias-tinted */

  /* --- Code blocks (owned geometry + alias colors) --- */
  --editor-code-bg: var(--muted, oklch(0.97 0 0)); /* alias */
  --editor-code-radius: var(--radius-md, 0.5rem); /* rounded-md */
  --editor-code-padding: 1rem; /* p-4 */
  --editor-code-gap-y: 0.75rem; /* my-3 */
  --editor-code-font-size: 0.875rem; /* text-sm */
  --editor-inline-code-bg: var(--muted, oklch(0.97 0 0)); /* alias */
  --editor-inline-code-radius: 0.375rem; /* rounded-md */
  --editor-inline-code-px: 0.375rem; /* px-1.5 */
  --editor-inline-code-py: 0.125rem; /* py-0.5 */

  /* --- Collapsible sections (owned geometry + alias colors) --- */
  --editor-collapsible-gap-y: 1rem; /* my-4 */
  --editor-collapsible-radius: var(
    --radius-md,
    0.5rem
  ); /* capped at rounded-md */
  --editor-collapsible-border: var(--border, oklch(0.922 0 0)); /* alias */
  --editor-collapsible-bg: var(--card, oklch(1 0 0)); /* alias */
  --editor-collapsible-foreground: var(
    --card-foreground,
    oklch(0.145 0 0)
  ); /* alias */
  --editor-collapsible-header-px: 1rem; /* px-4 */
  --editor-collapsible-header-py: 0.75rem; /* py-3 */
  --editor-collapsible-indent: 2.5rem; /* pl-10 */
  --editor-collapsible-title-border: color-mix(
    in oklch,
    var(--border, oklch(0.922 0 0)) 70%,
    transparent
  ); /* alias-tinted */

  /* --- Multi-column layout (owned geometry + alias colors) --- */
  --editor-layout-gap-y: 1rem; /* my-4 */
  --editor-layout-gap: 0.75rem; /* gap-3 */
  --editor-layout-gap-md: 1rem; /* md:gap-4 */
  --editor-layout-radius: var(--radius-md, 0.5rem); /* capped at rounded-md */
  --editor-layout-border: color-mix(
    in oklch,
    var(--border, oklch(0.922 0 0)) 70%,
    transparent
  ); /* alias-tinted */
  --editor-layout-bg: color-mix(
    in oklch,
    var(--muted, oklch(0.97 0 0)) 20%,
    transparent
  ); /* alias-tinted */
  --editor-layout-padding: 0.75rem; /* p-3 */
  --editor-layout-item-radius: var(--radius-md, 0.5rem); /* rounded-md */
  --editor-layout-item-border: color-mix(
    in oklch,
    var(--border, oklch(0.922 0 0)) 80%,
    transparent
  ); /* alias-tinted */
  --editor-layout-item-bg: color-mix(
    in oklch,
    var(--background, oklch(1 0 0)) 80%,
    transparent
  ); /* alias-tinted */
  --editor-layout-item-padding: 0.75rem; /* p-3 */
  --editor-layout-preview-bg: color-mix(
    in oklch,
    var(--muted, oklch(0.97 0 0)) 40%,
    transparent
  ); /* alias-tinted */
  --editor-layout-preview-padding: 0.5rem; /* p-2 */
  --editor-layout-preview-gap: 0.5rem; /* gap-2 */
  --editor-layout-preview-cell-radius: 0.375rem; /* rounded-md */
  --editor-layout-preview-cell-bg: color-mix(
    in oklch,
    var(--background, oklch(1 0 0)) 90%,
    transparent
  ); /* alias-tinted */
  --editor-layout-option-radius: var(
    --radius-md,
    0.5rem
  ); /* capped at rounded-md */
  --editor-layout-option-border: color-mix(
    in oklch,
    var(--border, oklch(0.922 0 0)) 80%,
    transparent
  ); /* alias-tinted */
  --editor-layout-option-px: 1rem; /* px-4 */
  --editor-layout-option-py: 1rem; /* py-4 */

  /* --- Math equations (owned geometry + alias colors) --- */
  --editor-math-radius: 0.25rem; /* rounded */
  --editor-math-px: 0.375rem; /* px-1.5 */
  --editor-math-py: 0.125rem; /* py-0.5 */
  --editor-math-hover-bg: color-mix(
    in oklch,
    var(--muted, oklch(0.97 0 0)) 40%,
    transparent
  ); /* alias-tinted */
  --editor-math-selected-bg: color-mix(
    in oklch,
    var(--muted, oklch(0.97 0 0)) 30%,
    transparent
  ); /* alias-tinted */
  --editor-math-selected-ring: color-mix(
    in oklch,
    var(--primary, oklch(0.205 0 0)) 40%,
    transparent
  ); /* alias-tinted */
  --editor-math-block-gap-y: 0.5rem; /* my-2 */
  --editor-math-segment-bg: color-mix(
    in oklch,
    var(--muted, oklch(0.97 0 0)) 50%,
    transparent
  ); /* alias-tinted */
  --editor-math-segment-radius: 0.375rem; /* rounded-md */
  --editor-math-segment-padding: 0.125rem; /* p-0.5 */
  --editor-math-preview-min-h: 2.25rem; /* min-h-9 */
  --editor-math-preview-radius: 0.375rem; /* rounded-md */
  --editor-math-preview-border: color-mix(
    in oklch,
    var(--border, oklch(0.922 0 0)) 40%,
    transparent
  ); /* alias-tinted */
  --editor-math-preview-bg: color-mix(
    in oklch,
    var(--muted, oklch(0.97 0 0)) 20%,
    transparent
  ); /* alias-tinted */
  --editor-math-preview-padding: 0.5rem; /* p-2 */

  /* --- YouTube embeds + generic embed wrapper --- */
  --editor-embed-gap-y: 1rem; /* my-4 */
  --editor-youtube-radius: var(--radius-md, 0.5rem); /* capped at rounded-md */
  --editor-youtube-border: color-mix(
    in oklch,
