"use client";

import type { theme_palette, theme_styles } from "@twinkleplop/core";
import {
  dark as catppuccinDark,
  dark_styles as catppuccinDarkStyles,
  light as catppuccinLight,
  light_styles as catppuccinLightStyles,
} from "@twinkleplop/theme-catppuccin/tokens";
import {
  dark as githubDark,
  dark_styles as githubDarkStyles,
  light as githubLight,
  light_styles as githubLightStyles,
} from "@twinkleplop/theme-github/tokens";

import {
  dark as everforestDark,
  dark_styles as everforestDarkStyles,
  light as everforestLight,
  light_styles as everforestLightStyles,
} from "./everforest";
import {
  dark as nordDark,
  dark_styles as nordDarkStyles,
  light as nordLight,
  light_styles as nordLightStyles,
} from "./nord";

/**
 * Code-block theme families. Most families ship a light and a dark
 * palette and the active variant follows the app theme (`resolvedTheme`),
 * so one picker value covers both modes. Nord is the exception: the
 * reference ships dark-only, so the family is pinned to its dark variant
 * in both modes (see `resolveCodeBlockThemeId`).
 *
 * `github` and `catppuccin` are upstream Twinkleplop packages;
 * `nord` and `everforest` are local themes authored in this folder
 * (see `nord.ts` / `everforest.ts`).
 */
export const CODE_BLOCK_THEME_FAMILIES = [
  { label: "GitHub", value: "github" },
  { label: "Catppuccin", value: "catppuccin" },
  { label: "Nord", value: "nord" },
  { label: "Everforest", value: "everforest" },
] as const;

export type CodeBlockThemeFamily =
  (typeof CODE_BLOCK_THEME_FAMILIES)[number]["value"];

export type CodeBlockThemeMode = "light" | "dark";

/** Fully-resolved per-node theme id persisted on the Lexical `CodeNode`. */
export type CodeBlockThemeId = `${CodeBlockThemeFamily}-${CodeBlockThemeMode}`;

export const DEFAULT_CODE_BLOCK_THEME_FAMILY: CodeBlockThemeFamily = "nord";

/** Families pinned to a single variant in every app mode. */
const SINGLE_VARIANT_FAMILIES: Partial<
  Record<CodeBlockThemeFamily, CodeBlockThemeMode>
> = {
  // The Nord reference ships dark-only: keep the dark Polar Night block
  // (bg + verbatim token hues) even when the app runs in light mode.
  nord: "dark",
};

const PALETTES: Record<CodeBlockThemeId, theme_palette> = {
  "catppuccin-dark": catppuccinDark,
  "catppuccin-light": catppuccinLight,
  "everforest-dark": everforestDark,
  "everforest-light": everforestLight,
  "github-dark": githubDark,
  "github-light": githubLight,
  "nord-dark": nordDark,
  "nord-light": nordLight,
};

const STYLES: Record<CodeBlockThemeId, theme_styles> = {
  "catppuccin-dark": catppuccinDarkStyles,
  "catppuccin-light": catppuccinLightStyles,
  "everforest-dark": everforestDarkStyles,
  "everforest-light": everforestLightStyles,
  "github-dark": githubDarkStyles,
  "github-light": githubLightStyles,
  "nord-dark": nordDarkStyles,
  "nord-light": nordLightStyles,
};

export function isCodeBlockThemeFamily(
  value: unknown
): value is CodeBlockThemeFamily {
  return CODE_BLOCK_THEME_FAMILIES.some((family) => family.value === value);
}

export function resolveCodeBlockThemeId(
  family: CodeBlockThemeFamily,
  mode: CodeBlockThemeMode
): CodeBlockThemeId {
  const pinned = SINGLE_VARIANT_FAMILIES[family];
  return `${family}-${pinned ?? mode}`;
}

const FALLBACK_THEME_ID: CodeBlockThemeId = "github-light";

/** Block background overrides per resolved theme id.
 *
 * GitHub renders on the shadcn card surface instead of its upstream
 * `#ffffff` / `#0d1117` so code blocks sit on `--card` like the rest of
 * the chrome. Every other family keeps its palette `background_color`.
 * Fallbacks mirror `src/index.css` (`:root` / `.dark` `--card`).
 */
const CODE_BLOCK_BACKGROUND_OVERRIDES: Partial<
  Record<CodeBlockThemeId, string>
> = {
  "github-dark": "var(--card, oklch(0.205 0 0))",
  "github-light": "var(--card, oklch(1 0 0))",
};

/** Block background for a persisted node theme: override first, palette
 * `background_color` otherwise. Used both for `--editor-code-bg` and the
 * CodeNode inline style so the two never diverge. */
export function getCodeBlockBackground(
  theme: string | null | undefined
): string {
  if (theme !== null && theme !== undefined) {
    const override = (
      CODE_BLOCK_BACKGROUND_OVERRIDES as Record<string, string | undefined>
    )[theme];
    if (override) {
      return override;
    }
    const palette = (PALETTES as Record<string, theme_palette | undefined>)[
      theme
    ];
    if (palette?.["background_color"]) {
      return palette["background_color"] as string;
    }
  }
  return (
    CODE_BLOCK_BACKGROUND_OVERRIDES[FALLBACK_THEME_ID] ??
    (PALETTES[FALLBACK_THEME_ID]?.["background_color"] as string) ??
    "#ffffff"
  );
}

/** Palette for a persisted node theme; unknown ids fall back to GitHub light. */
export function getCodeBlockPalette(
  theme: string | null | undefined
): theme_palette {
  if (theme !== null && theme !== undefined) {
    const palette = (PALETTES as Record<string, theme_palette | undefined>)[
      theme
    ];
    if (palette) {
      return palette;
    }
  }
  return PALETTES[FALLBACK_THEME_ID] ?? githubLight;
}

/** Font-style map (`italic`/`bold`/…) for a persisted node theme. */
export function getCodeBlockStyles(
  theme: string | null | undefined
): theme_styles {
  if (theme !== null && theme !== undefined) {
    const styles = (STYLES as Record<string, theme_styles | undefined>)[theme];
    if (styles) {
      return styles;
    }
  }
  return STYLES[FALLBACK_THEME_ID] ?? githubLightStyles;
}

const FONT_STYLE_DECLARATIONS: Record<string, string> = {
  bold: "font-weight: bold;",
  italic: "font-style: italic;",
  strikethrough: "text-decoration: line-through;",
  underline: "text-decoration: underline;",
};

/**
 * Inline style for one token: its palette color plus any font styles
 * (italic comments, bold headings, …) the theme declares for the type.
 */
export function getCodeBlockTokenStyle(
  theme: string | null | undefined,
  tokenType: string
): string {
  const palette = getCodeBlockPalette(theme);
  const styles = getCodeBlockStyles(theme);
  let style = "";
  const color = palette[tokenType];
  if (color) {
    style += `color: ${color};`;
  }
  const tokenStyles = styles[tokenType];
  if (tokenStyles) {
    for (const tokenStyle of tokenStyles) {
      style += FONT_STYLE_DECLARATIONS[tokenStyle] ?? "";
    }
  }
  return style;
}

/**
 * Theme-gated token-role overrides for the JS/TS grammar family.
 *
 * The Everforest palettes in `everforest.ts` are a verbatim port of the
 * official Shiki `tokenColors`, but Twinkleplop's static grammars assign
 * coarser roles than the reference rendering: `import` and `from` are both
 * `keyword`, an imported component is a bare `identifier`, a declared
 * component is `function`, and JSX brackets collapse into `punctuation`.
 * The reference (VS Code Everforest) renders module keywords
 * (`import`/`export`/`function`) plain, PascalCase values as types,
 * capitalized JSX tags as types, JSX brackets as operators, and JSX props
 * plain — no global palette remap can express that, because e.g. `keyword`
 * must stay red for `from`/`return` while going plain for `import`.
 *
 * The Nord palette in `nord.ts` is likewise verbatim, and its reference
 * (VS Code Nord) colors JSX tag brackets, statement terminators, and tag
 * names frost blue (`punctuation.definition.tag`,
 * `punctuation.terminator`, `entity.name.tag` → `#81A1C1`) while
 * declaration keywords (`export`, `function`) and JSX props render plain
 * — all coarser in Twinkleplop (`punctuation`/`tag_name`/`keyword`/
 * `attr_name`), so Nord gets its own small rule set below. Declared
 * bindings surface as `constant` from the grammar but are plain
 * `variable.other` in the reference, so they resolve to base text too. (`tag_name`
 * already carries the blue tag rule in the palette; the explicit
 * `tag_name` → `tag` mapping below keeps the resolution stable even if
 * the two entries ever diverge.)
 *
 * `resolveThemedTokenType` is a text-aware, theme-gated role resolver:
 * given the persisted node theme, the normalized grammar key, and the raw
 * token, it returns the token type whose palette entry should style the
 * token. The tokenizer stores the resolved type as the node's highlight
 * type too, so the token audit (`getCodeBlockTokenStyle(theme, type)`)
 * stays self-consistent.
 *
 * Scoped to `everforest-*`/`nord-*` + `tsx`/`typescript`/`javascript`
 * only; every other theme or language is the identity function.
 */

const EVERFOREST_FAMILY_PREFIX = "everforest-";
const NORD_FAMILY_PREFIX = "nord-";

/** Grammar keys (post-alias) these overrides apply to. */
const JS_FAMILY_LANGUAGES = new Set(["tsx", "typescript", "javascript"]);

/**
 * Module-structure keywords the reference renders plain (base text)
 * instead of red. Control-flow keywords (`from`, `return`, `if`, …)
 * keep the red `keyword` entry.
 */
const PLAIN_KEYWORDS = new Set(["import", "export", "function", "default"]);

/** JSX bracket fragments (optionally trailed by `;`, as Twinkleplop merges `/>;`). */
const JSX_BRACKET_PATTERN = /^(?:<\/?|\/?>);?$/u;

/** PascalCase values read as components/types in the reference. */
const PASCAL_CASE_PATTERN = /^[A-Z]/u;

/** Standalone statement terminators (`punctuation.terminator` in Nord). */
const SEMICOLON_PATTERN = /^;$/u;

/**
 * Declaration-structure keywords the Nord reference renders plain (base
 * text) instead of frost blue: `export`/`function`/`const`/`let`/`var`
 * stay Snow Storm while control-flow/module keywords (`import`, `from`,
 * `return`, `if`, …) keep the blue `keyword` entry.
 */
const NORD_PLAIN_KEYWORDS = new Set([
  "export",
  "function",
  "const",
  "let",
  "var",
]);

function resolveEverforestTokenType(tokenType: string, text: string): string {
  if (tokenType === "keyword" && PLAIN_KEYWORDS.has(text)) {
    return "identifier";
  }
  if (
    (tokenType === "identifier" ||
      tokenType === "function" ||
      tokenType === "tag_name") &&
    PASCAL_CASE_PATTERN.test(text)
  ) {
    return "type";
  }
  if (tokenType === "attr_name") {
    return "identifier";
  }
  if (tokenType === "punctuation" && JSX_BRACKET_PATTERN.test(text)) {
    return "operator";
  }
  return tokenType;
}

function resolveNordTokenType(tokenType: string, text: string): string {
  // Declaration keywords render plain (base text), not frost blue.
  if (tokenType === "keyword" && NORD_PLAIN_KEYWORDS.has(text)) {
    return "identifier";
  }
  // JSX props render plain (base text), not teal. Object-literal keys are
  // a separate `property` role and are unaffected.
  if (tokenType === "attr_name") {
    return "identifier";
  }
  // Declared bindings (`const x`, destructured names, `useState` pairs)
  // come out as `constant` from the grammar but are plain variables
  // (`variable.other`) in the reference — render them base text, not
  // frost blue. Genuine language constants keep their own roles
  // (`boolean`, `null`/`undefined` via `keyword`) and stay blue.
  if (tokenType === "constant") {
    return "identifier";
  }
  // Brackets/terminators follow `entity.name.tag`-adjacent frost blue, not
  // the Snow Storm punctuation entry. Tag names already carry the blue
  // `tag` rule in the palette; the explicit branch below keeps the
  // resolution pinned to it.
  if (tokenType === "tag_name") {
    return "tag";
  }
  if (
    tokenType === "punctuation" &&
    // Tag brackets and terminators are frost blue; braces, parens,
    // commas, and dots keep the Snow Storm punctuation entry.
    (JSX_BRACKET_PATTERN.test(text) || SEMICOLON_PATTERN.test(text))
  ) {
    return "operator";
  }
  return tokenType;
}

export function resolveThemedTokenType(
  theme: string | null | undefined,
  language: string,
  tokenType: string,
  text: string
): string {
  if (typeof theme !== "string" || !JS_FAMILY_LANGUAGES.has(language)) {
    return tokenType;
  }
  if (theme.startsWith(EVERFOREST_FAMILY_PREFIX)) {
    return resolveEverforestTokenType(tokenType, text);
  }
  if (theme.startsWith(NORD_FAMILY_PREFIX)) {
    return resolveNordTokenType(tokenType, text);
  }
  return tokenType;
}

"use client";

import { $createCodeHighlightNode } from "@lexical/code";
import type { CodeNode } from "@lexical/code";
import type { Tokenizer } from "@lexical/code-shiki";
import { tokenize as tokenizeBash } from "@twinkleplop/bash";
import { tokenize as tokenizeCss } from "@twinkleplop/css";
import { tokenize as tokenizeDiff } from "@twinkleplop/diff";
import { tokenize as tokenizeDotenv } from "@twinkleplop/dotenv";
import { tokenize as tokenizeGo } from "@twinkleplop/go";
import { tokenize as tokenizeHtml } from "@twinkleplop/html";
