  getCodeBlockBackground,
  getCodeBlockPalette,
  getCodeBlockTokenStyle,
} from "./themes/registry";
import { resolveThemedTokenType } from "./themes/token-roles";

type TokenizeFn = ReturnType<typeof tokenizeTypescript>;

const TOKENIZERS: Record<string, TokenizeFn> = {
  bash: tokenizeBash(),
  css: tokenizeCss(),
  diff: tokenizeDiff(),
  dotenv: tokenizeDotenv(),
  go: tokenizeGo(),
  html: tokenizeHtml(),
  http: tokenizeHttp(),
  ini: tokenizeIni(),
  javascript: tokenizeJavascript(),
  json: tokenizeJson(),
  jsonc: tokenizeJsonc(),
  markdown: tokenizeMarkdown(),
  python: tokenizePython(),
  rust: tokenizeRust(),
  shellsession: tokenizeShellsession(),
  sql: tokenizeSql(),
  svelte: tokenizeSvelte(),
  toml: tokenizeToml(),
  tsx: tokenizeTsx(),
  typescript: tokenizeTypescript(),
  yaml: tokenizeYaml(),
};

const LANGUAGE_ALIASES = CODE_LANGUAGE_ALIASES;

const DEFAULT_LANGUAGE = DEFAULT_CODE_LANGUAGE;

/** Active palette/style helpers live in the theme registry. */

/**
 * Twinkleplop only emits meaningful tokens — whitespace, indentation and
 * newlines are gaps between triplets. Lexical needs explicit nodes for
 * those, so gap text is re-emitted as plain text / tab / line-break nodes.
 */
const pushGapNodes = (nodes: LexicalNode[], gap: string): void => {
  const lines = gap.split("\n");
  for (let lineIndex = 0; lineIndex < lines.length; lineIndex += 1) {
    if (lineIndex > 0) {
      nodes.push($createLineBreakNode());
    }
    const parts = (lines[lineIndex] ?? "").split("\t");
    for (let partIndex = 0; partIndex < parts.length; partIndex += 1) {
      if (partIndex > 0) {
        nodes.push($createTabNode());
      }
      const part = parts[partIndex] ?? "";
      if (part !== "") {
        nodes.push($createCodeHighlightNode(part));
      }
    }
  }
};

const pushTokenNodes = (
  nodes: LexicalNode[],
  text: string,
  highlightType: string,
  style: string
): void => {
  const lines = text.split("\n");
  for (let lineIndex = 0; lineIndex < lines.length; lineIndex += 1) {
    if (lineIndex > 0) {
      nodes.push($createLineBreakNode());
    }
    const parts = (lines[lineIndex] ?? "").split("\t");
    for (let partIndex = 0; partIndex < parts.length; partIndex += 1) {
      if (partIndex > 0) {
        nodes.push($createTabNode());
      }
      const part = parts[partIndex] ?? "";
      if (part === "") {
        continue;
      }
      const node = $createCodeHighlightNode(part, highlightType);
      if (style !== "") {
        node.setStyle(style);
      }
      nodes.push(node);
    }
  }
};

/**
 * Drop-in `Tokenizer` for `registerCodeHighlighting` backed by Twinkleplop
 * instead of Shiki. Mirrors the Shiki tokenizer contract: per-node theme
 * drives the light/dark palette, node bg/fg lands on the CodeNode style,
 * and each token becomes a CodeHighlightNode with an inline color.
 */
export const TwinkleplopTokenizer: Tokenizer = {
  $tokenize(codeNode: CodeNode, language?: string): LexicalNode[] {
    const rawLanguage = (language ?? codeNode.getLanguage() ?? DEFAULT_LANGUAGE)
      .trim()
      .toLowerCase();
    const grammarKey = LANGUAGE_ALIASES[rawLanguage] ?? DEFAULT_LANGUAGE;

    const code = codeNode.getTextContent();
    if (code === "") {
      return [];
    }

    const theme = codeNode.getTheme() ?? this.defaultTheme;
    const palette = getCodeBlockPalette(theme);
    const background = getCodeBlockBackground(theme);
    const foreground = palette["identifier"];
    let nodeStyle = "";
    if (background) {
      nodeStyle += `background-color: ${background};`;
    }
    if (foreground) {
      nodeStyle += `color: ${foreground};`;
    }
    if (codeNode.getStyle() !== nodeStyle) {
      codeNode.setStyle(nodeStyle);
    }

    // Plain-text blocks keep uncolored nodes: no grammar pass, just
    // whitespace-aware plain nodes so content is never wiped.
    if (grammarKey === "plaintext") {
      const nodes: LexicalNode[] = [];
      pushGapNodes(nodes, code);
      return nodes;
    }

    const tokenizeFn = TOKENIZERS[grammarKey] ?? TOKENIZERS[DEFAULT_LANGUAGE];
    if (!tokenizeFn) {
      return [];
    }

    let result: ReturnType<TokenizeFn>;
    try {
      result = tokenizeFn(code);
    } catch {
      return [];
    }

    const nodes: LexicalNode[] = [];
    const { token_types, tokens } = result;
    let cursor = 0;
    for (let i = 0; i < tokens.length; i += 3) {
      const typeIndex = tokens[i] as number;
      const start = tokens[i + 1] as number;
      const end = tokens[i + 2] as number;
      if (start > cursor) {
        pushGapNodes(nodes, code.slice(cursor, start));
      }
      const tokenType = token_types[typeIndex] ?? "identifier";
      const tokenText = code.slice(start, end);
      // Everforest re-assigns a few JS/TS roles toward the reference
      // rendering (plain `import`, PascalCase values as types, orange JSX
      // brackets, plain props). The resolved type doubles as highlight
      // type so the token audit stays self-consistent.
      const displayType = resolveThemedTokenType(
        theme,
        grammarKey,
        tokenType,
        tokenText
      );
      pushTokenNodes(
        nodes,
        tokenText,
        displayType,
        getCodeBlockTokenStyle(theme, displayType)
      );
      cursor = end;
    }
    if (cursor < code.length) {
      pushGapNodes(nodes, code.slice(cursor));
    }
    return nodes;
  },
  defaultLanguage: DEFAULT_LANGUAGE,
  defaultTheme: "nord-dark",
};

"use client";

import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext";
import { useEffect } from "react";

interface EditablePluginProps {
  editable: boolean;
}

export function EditablePlugin({ editable }: EditablePluginProps) {
  const [editor] = useLexicalComposerContext();

  useEffect(() => {
    editor.setEditable(editable);
  }, [editor, editable]);

  return null;
}

"use client";

import type { Transformer } from "@lexical/markdown";
import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext";
import type { LexicalEditor } from "lexical";
import { useEffect, useEffectEvent, useRef, useState } from "react";

import { DEFAULT_EDITOR_SNAPSHOT_OPTIONS } from "../../core/composition";
import type { ResolvedEditorSnapshotOptions } from "../../core/composition";
import { EDITOR_SEED_UPDATE_TAG } from "../../core/constants";
import type { EditorSnapshot } from "../../core/types";
import {
  loadMarkdownContent,
  readEditorSnapshot,
  readEditorTextContent,
  replaceEditorHtmlContent,
} from "../../core/utils";
import type { SnapshotUpdateSignal } from "./snapshot-update";
import { shouldEmitSnapshotUpdate } from "./snapshot-update";

export interface EditorStatePluginProps {
  initialHtml?: string;
  initialMarkdown?: string;
  onChange?: (textContent: string, editor: LexicalEditor) => void;
  onSnapshotReady?: (snapshot: EditorSnapshot, editor: LexicalEditor) => void;
  /**
   * When true the seed was already applied synchronously through the
   * composer's `initialConfig.editorState` — no post-mount seeding is done,
   * only the optional initial snapshot emission is replayed here.
   */
  seededViaConfig?: boolean;
  /**
   * Resolved snapshot serialization options (see `features.snapshot` on
   * `Editor`). Disabled outputs are skipped entirely; defaults to all-on.
   */
  snapshotOptions?: ResolvedEditorSnapshotOptions;
  transformers?: readonly Transformer[];
}

export function EditorStatePlugin({
  initialHtml,
  initialMarkdown,
  onChange,
  onSnapshotReady,
  seededViaConfig = false,
  snapshotOptions = DEFAULT_EDITOR_SNAPSHOT_OPTIONS,
  transformers,
}: EditorStatePluginProps) {
  const [editor] = useLexicalComposerContext();

  // `initial*` props are initial-only by contract: the seed is captured once
  // per mount and never re-applied when prop identities change. Consumers
  // remount via `key` instead — re-seeding in place would replace live state
  // and reset the caret.
  const [seed] = useState(() => ({
    html: initialHtml,
    markdown: initialMarkdown,
  }));

  const seedEditor = useEffectEvent(() => {
    if (seed.markdown) {
      loadMarkdownContent(editor, seed.markdown, {
        select: false,
        tag: EDITOR_SEED_UPDATE_TAG,
        transformers,
      });
      return;
    }

    if (seed.html) {
      replaceEditorHtmlContent(editor, seed.html, {
        select: false,
        tag: EDITOR_SEED_UPDATE_TAG,
      });
    }
  });

  const emitInitialSnapshot = useEffectEvent(() => {
    if (snapshotOptions.text) {
      onChange?.(readEditorTextContent(editor), editor);
    }

    if (snapshotOptions.html || snapshotOptions.markdown) {
      onSnapshotReady?.(
        readEditorSnapshot(editor, transformers, snapshotOptions),
        editor
      );
    }
  });

  // When the seed was applied through the composer's initial state there is
  // no seed update to observe, so the initial snapshot (when enabled) is
  // emitted directly from the already-populated state. The emission is
  // deferred one microtask because the composer's initial update commits
  // asynchronously (scheduleMicroTask) — this keeps the read deterministic
  // whether effects flush before or after that commit. The post-mount
  // seeding path remains for standalone plugin usage.
  const didEmitInitialRef = useRef(false);

  const emitConfiguredSeedSnapshot = useEffectEvent(() => {
    if (!snapshotOptions.emitInitialSnapshot) {
      return;
    }
    if (!(seed.markdown || seed.html)) {
      return;
    }
    if (didEmitInitialRef.current) {
      return;
    }
    didEmitInitialRef.current = true;
    queueMicrotask(() => {
      emitInitialSnapshot();
    });
  });

  const runMountSeed = useEffectEvent(() => {
    if (seededViaConfig) {
      emitConfiguredSeedSnapshot();
      return;
    }
    seedEditor();
  });

  useEffect(() => {
    runMountSeed();
  }, []);

  const handleUpdate = useEffectEvent((update: SnapshotUpdateSignal) => {
    if (!shouldEmitSnapshotUpdate(update, snapshotOptions)) {
      return;
    }

    if (snapshotOptions.text) {
      onChange?.(readEditorTextContent(editor), editor);
    }

    if (snapshotOptions.html || snapshotOptions.markdown) {
      onSnapshotReady?.(
        readEditorSnapshot(editor, transformers, snapshotOptions),
        editor
      );
    }
  });

  useEffect(() => editor.registerUpdateListener(handleUpdate), [editor]);

  return null;
}

"use client";

import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext";
import { $getRoot } from "lexical";
import { useEffect, useRef } from "react";

const SETTLE_RETRY_DELAY_MS = 150;

export function FocusOnMountPlugin() {
  const [editor] = useLexicalComposerContext();
  const retryTimersRef = useRef<number[]>([]);
  const didPlaceCaretRef = useRef(false);

  useEffect(() => {
    let cancelled = false;

    const clearRetryTimers = () => {
      for (const timer of retryTimersRef.current) {
        window.clearTimeout(timer);
      }
      retryTimersRef.current = [];
    };

    const placeMountCaret = () => {
      // Idempotent: once the mount caret is placed, never move it again.
      // Late triggers (window load, fonts.ready, fallback timer, retries)
      // would otherwise yank the caret back to the start of the first block
      // even after the user has already moved it.
      if (didPlaceCaretRef.current) {
        return true;
      }

      const rootElement = editor.getRootElement();
      if (rootElement?.contains(document.activeElement)) {
        didPlaceCaretRef.current = true;
        return true;
      }

      const hasContent = editor
        .getEditorState()
        .read(() => $getRoot().getFirstDescendant() !== null);
      if (!hasContent) {
        return false;
      }

      editor.update(() => {
        const root = $getRoot();
        const firstDescendant = root.getFirstDescendant();
        if (firstDescendant) {
          firstDescendant.selectStart();
        } else {
          const firstChild = root.getFirstChild();
          if (firstChild) {
            firstChild.selectStart();
          } else {
            root.selectStart();
          }
        }
      });

      if (rootElement) {
        rootElement.focus({ preventScroll: true });
      }
      didPlaceCaretRef.current = true;

      return true;
    };

    const settle = () => {
      if (cancelled) {
        return;
      }

      // Wait one frame so any in-flight layout pass is applied before the
      // caret is placed. Placing the caret before async assets (KaTeX fonts,
      // images) finish loading makes the browser scroll the caret back into
      // view when those assets later shift the layout, yanking the page away
      // from its position.
      requestAnimationFrame(() => {
        if (cancelled) {
          return;
        }

        if (!placeMountCaret()) {
          const retryTimer = window.setTimeout(settle, SETTLE_RETRY_DELAY_MS);
          retryTimersRef.current.push(retryTimer);
        }
      });
    };

    const release = () => {
      if (cancelled) {
        return;
      }
      cancelled = true;
      window.removeEventListener("load", settle);
      clearRetryTimers();
    };

    window.addEventListener("load", settle);
    const fontsReady = document.fonts
      ? document.fonts.ready
      : Promise.resolve();
    // `settle` runs for both outcomes (fonts loaded or failed), matching the
    // previous `.then(settle).catch(settle)` chain.
    void (async () => {
      try {
        await fontsReady;
      } catch {
        // Font loading is best-effort; the caret is placed regardless.
      }
      settle();
    })();
    const fallbackTimer = window.setTimeout(settle, 1000);

    return () => {
      release();
      window.clearTimeout(fallbackTimer);
    };
  }, [editor]);

  return null;
}

"use client";

import {
  $createHorizontalRuleNode,
  $isHorizontalRuleNode,
  HorizontalRuleNode,
  INSERT_HORIZONTAL_RULE_COMMAND,
} from "@lexical/extension";
import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext";
import {
  $insertNodeToNearestRoot,
  addClassNamesToElement,
  mergeRegister,
  removeClassNamesFromElement,
} from "@lexical/utils";
import {
  $createNodeSelection,
  $getNodeFromDOMNode,
  $getSelection,
  $isNodeSelection,
  $isParagraphNode,
  $isRangeSelection,
  $isRootOrShadowRoot,
  $isTextNode,
  $setSelection,
  CLICK_COMMAND,
  COMMAND_PRIORITY_EDITOR,
  COMMAND_PRIORITY_LOW,
  KEY_ENTER_COMMAND,
} from "lexical";
import type { LexicalNode } from "lexical";
import { useEffect } from "react";

import { $replaceWithHorizontalRule } from "../markdown/transformers";

const toggleNodeSelection = (node: LexicalNode, shiftKey = false) => {
  const selection = $getSelection();
  const wasSelected = node.isSelected();
  const key = node.getKey();
  const nodeSelection =
    shiftKey && $isNodeSelection(selection)
      ? selection
      : $createNodeSelection();

  if (!($isNodeSelection(selection) && shiftKey)) {
    $setSelection(nodeSelection);
  }

  if (wasSelected) {
    nodeSelection.delete(key);
    return;
  }

  nodeSelection.add(key);
};

const getClickedHorizontalRuleNode = (target: EventTarget | null) => {
  if (!(target instanceof Node)) {
    return null;
  }

  const node = $getNodeFromDOMNode(target);
  return $isHorizontalRuleNode(node) ? node : null;
};

const syncHorizontalRuleSelectionClass = (
  editor: ReturnType<typeof useLexicalComposerContext>[0],
  nodeKey: string,
  selectedClassName: string
) => {
  const element = editor.getElementByKey(nodeKey);
  if (!element) {
    return;
  }

  const node = $getNodeFromDOMNode(element);
  if (!$isHorizontalRuleNode(node)) {
    return;
  }

  if (node.isSelected()) {
    addClassNamesToElement(element, selectedClassName);
    return;
  }

  removeClassNamesFromElement(element, selectedClassName);
};

const registerHorizontalRuleInsertCommand = (
  editor: ReturnType<typeof useLexicalComposerContext>[0]
) =>
  editor.registerCommand(
    INSERT_HORIZONTAL_RULE_COMMAND,
    () => {
      const selection = $getSelection();
      if (!$isRangeSelection(selection)) {
        return false;
      }

      $insertNodeToNearestRoot($createHorizontalRuleNode());
      return true;
    },
    COMMAND_PRIORITY_EDITOR
  );

const registerHorizontalRuleClickCommand = (
  editor: ReturnType<typeof useLexicalComposerContext>[0]
) =>
  editor.registerCommand(
    CLICK_COMMAND,
    (event) => {
      const node = getClickedHorizontalRuleNode(event.target);
      if (!node) {
        return false;
      }

      toggleNodeSelection(node, event.shiftKey);
      return true;
    },
    COMMAND_PRIORITY_LOW
  );

const registerHorizontalRuleEnterShortcut = (
  editor: ReturnType<typeof useLexicalComposerContext>[0]
) =>
  editor.registerCommand(
    KEY_ENTER_COMMAND,
    (event) => {
      if (event?.shiftKey) {
        return false;
      }

      const selection = $getSelection();
      if (!($isRangeSelection(selection) && selection.isCollapsed())) {
        return false;
      }

      const anchorNode = selection.anchor.getNode();
      if (!$isTextNode(anchorNode)) {
        return false;
      }

      const parentNode = anchorNode.getParent();
      if (
        parentNode === null ||
        !$isParagraphNode(parentNode) ||
        !$isRootOrShadowRoot(parentNode.getParent()) ||
        parentNode.getChildrenSize() !== 1 ||
        parentNode.getFirstChild() !== anchorNode ||
        parentNode.getTextContent() !== "---" ||
        selection.anchor.offset !== anchorNode.getTextContent().length
      ) {
        return false;
      }

      $replaceWithHorizontalRule(parentNode, true);
      if (event !== null) {
        event.preventDefault();
      }
      return true;
    },
    COMMAND_PRIORITY_LOW
  );

const registerHorizontalRuleMutationListener = (
  editor: ReturnType<typeof useLexicalComposerContext>[0],
  selectedClassName: string
) =>
  editor.registerMutationListener(HorizontalRuleNode, (nodes) => {
    editor.read(() => {
      for (const [nodeKey, mutation] of nodes) {
        if (mutation === "destroyed") {
          continue;
        }

        syncHorizontalRuleSelectionClass(editor, nodeKey, selectedClassName);
      }
    });
  });

export function HorizontalRulePlugin() {
  const [editor] = useLexicalComposerContext();

  useEffect(() => {
    const hrSelectedClassName = editor._config.theme.hrSelected ?? "selected";

    return mergeRegister(
      registerHorizontalRuleInsertCommand(editor),
      registerHorizontalRuleClickCommand(editor),
      registerHorizontalRuleEnterShortcut(editor),
      registerHorizontalRuleMutationListener(editor, hrSelectedClassName)
    );
  }, [editor]);

  return null;
}

import type { EditorState } from "lexical";
import { HISTORY_MERGE_TAG } from "lexical";

import { EDITOR_SEED_UPDATE_TAG } from "../../core/constants";

/** Structural subset of Lexical's update-listener payload used for filtering. */
export interface SnapshotUpdateSignal {
  dirtyElements: { readonly size: number };
  dirtyLeaves: { readonly size: number };
  prevEditorState: EditorState;
  tags: ReadonlySet<string>;
}

/**
 * Decides whether an editor update should produce serialized outputs.
 * Mirrors OnChangePlugin semantics (selection-only, history-merge and
 * initial-empty updates are ignored) plus suppression of the tagged mount
 * seed when `emitInitialSnapshot` is `false`.
 */
export const shouldEmitSnapshotUpdate = (
  update: SnapshotUpdateSignal,
  options: { emitInitialSnapshot: boolean }
): boolean => {
  if (update.dirtyElements.size === 0 && update.dirtyLeaves.size === 0) {
    return false;
  }
  if (update.tags.has(HISTORY_MERGE_TAG)) {
    return false;
  }
  if (update.prevEditorState.isEmpty()) {
    return false;
  }
  if (!options.emitInitialSnapshot && update.tags.has(EDITOR_SEED_UPDATE_TAG)) {
    return false;
  }
  return true;
};

import { createCommand } from "lexical";

/**
 * Dispatched by the default action bar (or any consumer surface) to export the
 * current editor document to a `.md` file. The `MarkdownExportPlugin` owns the
 * handler so the conversion logic stays lego-scoped and reusable outside the
 * built-in chrome.
 */
export const EXPORT_MARKDOWN_COMMAND = createCommand<undefined>(
  "export-markdown-command"
);

import type { Transformer } from "@lexical/markdown";
import type { LexicalEditor } from "lexical";

import { downloadMarkdownContent } from "../../core/actions";
import { readEditorSnapshot } from "../../core/utils";

/**
 * Derives a filesystem-safe name from the first non-empty line of the
 * document, falling back to `document` when the editor is blank.
 */
export const getMarkdownExportFilename = (textContent: string): string => {
  const firstLine = textContent
    .split("\n")
    .find((line) => line.trim().length > 0);

  const slugified = (firstLine ?? "document")
    .trim()
    .toLowerCase()
    .replaceAll(/[^a-z0-9]+/gu, "-")
    .replaceAll(/^-+|-+$/gu, "")
    .slice(0, 60);

  return slugified || "document";
};

/**
 * Serializes the current editor state to markdown (via `$convertToMarkdownString`,
 * the same path the output panel uses) and downloads it as a `.md` file.
 */
export const exportMarkdownToFile = (
  editor: LexicalEditor,
  transformers: readonly Transformer[]
) => {
  const snapshot = readEditorSnapshot(editor, transformers);
  downloadMarkdownContent(
    snapshot.markdown,
    getMarkdownExportFilename(snapshot.text)
  );
};

"use client";

import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext";
import { COMMAND_PRIORITY_LOW } from "lexical";
import { useEffect } from "react";

import { useEditorTransformers } from "../../core/editor-transformers-context";
import { EXPORT_MARKDOWN_COMMAND } from "./commands";
import { exportMarkdownToFile } from "./export";

/**
 * Feature entrypoint for markdown export. Registers the export command against
 * the live editor so any surface (default action bar, consumer chrome) can
 * trigger a `.md` download with a single dispatch.
 *
 * Mounted for both editable and read-only modes: read-only documents should
 * stay exportable.
 */
export function MarkdownExportPlugin() {
  const [editor] = useLexicalComposerContext();
  const transformers = useEditorTransformers();

  useEffect(
    () =>
      editor.registerCommand(
        EXPORT_MARKDOWN_COMMAND,
        () => {
          exportMarkdownToFile(editor, transformers);
          return true;
        },
        COMMAND_PRIORITY_LOW
      ),
    [editor, transformers]
  );

  return null;
}

import {
  $createLinkNode,
  $isAutoLinkNode,
  $isLinkNode,
  TOGGLE_LINK_COMMAND,
} from "@lexical/link";
import { $patchStyleText } from "@lexical/selection";
import {
  $createTextNode,
  $getSelection,
  $isRangeSelection,
  $isTextNode,
  FORMAT_ELEMENT_COMMAND,
  FORMAT_TEXT_COMMAND,
} from "lexical";
import type { LexicalEditor } from "lexical";

import {
  isValidEditorLinkUrl,
  normalizeEditorLinkUrl,
} from "../link-behavior/utils";
import {
  getFloatingToolbarSelectedNode,
  getSelectedLinkNode,
} from "./selection";

export const submitToolbarLink = (
  editor: LexicalEditor,
  linkUrl: string
): string => {
  const normalizedLinkUrl = normalizeEditorLinkUrl(linkUrl);

  if (isValidEditorLinkUrl(normalizedLinkUrl)) {
    editor.update(() => {
      editor.dispatchCommand(TOGGLE_LINK_COMMAND, normalizedLinkUrl);

      const selection = $getSelection();
      if (!$isRangeSelection(selection)) {
        return;
      }

      const selectedNode = getFloatingToolbarSelectedNode(selection);
      const linkNode = getSelectedLinkNode(selectedNode);
      if (!$isAutoLinkNode(linkNode)) {
        return;
      }

      const replacementLinkNode = $createLinkNode(linkNode.getURL(), {
        rel: linkNode.__rel,
        target: linkNode.__target,
        title: linkNode.__title,
      });
      linkNode.replace(replacementLinkNode, true);
    });
  } else {
    editor.dispatchCommand(TOGGLE_LINK_COMMAND, null);
  }

  return "";
};

export const clearToolbarLink = (editor: LexicalEditor) => {
  editor.dispatchCommand(TOGGLE_LINK_COMMAND, null);
};

/**
 * Replaces the selected link's display text, keeping the caret inside the
 * link. An empty value is a no-op (the existing text is kept) so clearing
 * the field by accident never wipes the label.
 */
export const submitToolbarLinkText = (
  editor: LexicalEditor,
  linkText: string
) => {
  editor.update(() => {
    const selection = $getSelection();
    if (!$isRangeSelection(selection)) {
      return;
    }

    const selectedNode = getFloatingToolbarSelectedNode(selection);
    const linkNode = getSelectedLinkNode(selectedNode);
    if (!($isLinkNode(linkNode) || $isAutoLinkNode(linkNode))) {
      return;
    }

    if (!linkText || linkText === linkNode.getTextContent()) {
      return;
    }

    // Splice-replace the children in one step: inserting the replacement
    // before removing the old ones keeps the selection anchored to a live
    // node. `clear()` + `append()` removes the selected child first, which
    // trips Lexical's lost-selection repair and silently rolls the whole
    // update back — the edited title never reaches the editor.
    const firstChild = linkNode.getFirstChild();
    const textNode = $createTextNode(linkText);
    if ($isTextNode(firstChild)) {
      textNode.setFormat(firstChild.getFormat());
      textNode.setStyle(firstChild.getStyle());
    }
    linkNode.splice(0, linkNode.getChildrenSize(), [textNode]);
    textNode.select();
  });
};

/**
 * Applies the card's URL + text drafts and moves the caret just after the
 * link. Collapsing outside the link is what lets the card close on Enter:
 * a selection still inside a single link would otherwise re-open it on the
 * next sync.
 */
export const applyToolbarLink = (
  editor: LexicalEditor,
  linkUrl: string,
  linkText: string
) => {
  submitToolbarLink(editor, linkUrl);
  submitToolbarLinkText(editor, linkText);
  editor.update(() => {
    const selection = $getSelection();
    if (!$isRangeSelection(selection)) {
      return;
    }

    const selectedNode = getFloatingToolbarSelectedNode(selection);
    const linkNode = getSelectedLinkNode(selectedNode);
    linkNode?.selectNext();
  });
};

export type ToggleableTextFormat =
  | "bold"
  | "italic"
  | "underline"
  | "strikethrough"
  | "code"
  | "highlight"
  | "subscript"
  | "superscript";

export const toggleToolbarFormat = (
  editor: LexicalEditor,
  format: ToggleableTextFormat
) => {
  editor.dispatchCommand(FORMAT_TEXT_COMMAND, format);
};

/**
 * Applies a horizontal alignment to the current block-level selection.
 * Passing `""` resets it (left in LTR documents).
 */
export const alignToolbarSelection = (
  editor: LexicalEditor,
  align: "left" | "center" | "right" | "justify" | ""
) => {
  editor.dispatchCommand(FORMAT_ELEMENT_COMMAND, align);
};

/**
 * Applies an inline `color` CSS property to the current Lexical selection.
 * Passing an empty string removes the property from all selected text nodes.
 */
export const applyTextColor = (editor: LexicalEditor, color: string) => {
  editor.update(() => {
    const selection = $getSelection();
    if (selection !== null) {
      $patchStyleText(selection, { color: color || null });
    }
  });
};

/**
 * Applies an inline `background-color` CSS property to the current Lexical
 * selection.  Passing an empty string removes the property.
 */
export const applyBgColor = (editor: LexicalEditor, color: string) => {
  editor.update(() => {
    const selection = $getSelection();
    if (selection !== null) {
      $patchStyleText(selection, { "background-color": color || null });
    }
  });
};

