export function FloatingToolbarPlugin() {
  const [editor] = useLexicalComposerContext();
  const toolbarRef = useRef<HTMLDivElement>(null);
  const commandIds = useEditorResolvedCommands();

  const [isVisible, setIsVisible] = useState(false);
  const [position, setPosition] = useState<FloatingToolbarPosition>(
    EMPTY_TOOLBAR_POSITION
  );
  const [formats, setFormats] =
    useState<FloatingToolbarFormatState>(DEFAULT_FORMAT_STATE);
  const [blockType, setBlockType] = useState<BlockTypeValue>("paragraph");

  // The raw position anchors the toolbar at the selection midpoint; the
  // rendered box is clamped against the measured toolbar size so it never
  // overflows the browser viewport. Runs pre-paint (no flicker) whenever
  // the anchor moves.
  const [adjustedPosition, setAdjustedPosition] =
    useState<FloatingToolbarPosition>(EMPTY_TOOLBAR_POSITION);

  useLayoutEffect(() => {
    if (!isVisible) {
      return;
    }
    const toolbar = toolbarRef.current;
    if (!toolbar) {
      return;
    }

    const next = clampFloatingToolbarPosition({
      position,
      toolbar: { height: toolbar.offsetHeight, width: toolbar.offsetWidth },
      viewport: { height: window.innerHeight, width: window.innerWidth },
    });

    setAdjustedPosition((current) =>
      areFloatingToolbarPositionsEqual(current, next) ? current : next
    );
  }, [isVisible, position]);
  /*
   * When a color picker popover or the "Turn into" dropdown is open we skip
   * visibility/position updates so the floating toolbar stays alive while the
   * user interacts with floating surfaces. A ref (rather than state) is used
   * to avoid re-registering the update listener on every open/close cycle.
   */
  const openSurfaceCountRef = useRef(0);

  // Set when the user opens the link card from this toolbar. While it is
  // set and the selection still lives inside a single link, the toolbar
  // stays closed: the card is the active editing surface. The flag clears
  // once the selection leaves the link.
  const linkEditorOpenRef = useRef(false);

  const updateToolbar = useEffectEvent(() => {
    editor.getEditorState().read(() => {
      const toolbarState = readFloatingToolbarState();

      setFormats((currentFormats) =>
        areFloatingToolbarFormatsEqual(currentFormats, toolbarState.formats)
          ? currentFormats
          : toolbarState.formats
      );

      // Read inside the Lexical read() scope; the updater only compares.
      const nextBlockType = getBlockTypeFromSelection();
      if (nextBlockType) {
        setBlockType((currentBlockType) =>
          currentBlockType === nextBlockType ? currentBlockType : nextBlockType
        );
      }

      if (linkEditorOpenRef.current) {
        if (toolbarState.linkUrl !== "") {
          setIsVisible((currentIsVisible) =>
            currentIsVisible ? false : currentIsVisible
          );
          return;
        }
        linkEditorOpenRef.current = false;
      }

      if (openSurfaceCountRef.current === 0) {
        setIsVisible((currentIsVisible) =>
          currentIsVisible === toolbarState.isVisible
            ? currentIsVisible
            : toolbarState.isVisible
        );
        setPosition((currentPosition) =>
          areFloatingToolbarPositionsEqual(
            currentPosition,
            toolbarState.position
          )
            ? currentPosition
            : toolbarState.position
        );
      }
    });
  });

  useEffect(
    () =>
      mergeRegister(
        editor.registerCommand(
          SELECTION_CHANGE_COMMAND,
          () => {
            updateToolbar();
            return false;
          },
          COMMAND_PRIORITY_LOW
        ),
        editor.registerUpdateListener(() => {
          updateToolbar();
        })
      ),
    [editor]
  );

  const handleLinkToggle = () => {
    if (formats.isLink) {
      editor.dispatchCommand(TOGGLE_LINK_COMMAND, null);
      return;
    }

    editor.dispatchCommand(TOGGLE_LINK_COMMAND, LINK_PLACEHOLDER_URL);
    editor.dispatchCommand(OPEN_FLOATING_LINK_EDITOR_COMMAND, undefined);
    linkEditorOpenRef.current = true;
    setIsVisible(false);
  };

  const handleSurfaceOpenChange = (open: boolean) => {
    openSurfaceCountRef.current += open ? 1 : -1;
  };

  if (!isVisible) {
    return null;
  }

  return createPortal(
    <div
      className="fixed z-50 -translate-x-1/2 -translate-y-full"
      ref={toolbarRef}
      style={{
        left: `${adjustedPosition.left}px`,
        top: `${adjustedPosition.top}px`,
      }}
    >
      <div
        aria-label="Formatting options"
        className={cn(
          "editor-floating editor-floating-padding-sm flex items-center gap-0.5",
          "animate-in duration-100 fade-in-0 zoom-in-95"
        )}
        role="toolbar"
      >
        <TooltipProvider>
          <BlockTypeDrop
            blockType={blockType}
            commandIds={commandIds}
            editor={editor}
            onOpenChange={handleSurfaceOpenChange}
            variant="compact"
          />

          <Separator className="mr-0.5 ml-1.5 h-5" orientation="vertical" />

          {TOOLBAR_FORMAT_ACTIONS.map((action) => {
            const Icon = action.icon;

            return (
              <ToolbarTooltip key={action.format} label={action.label}>
                <Toggle
                  aria-label={action.label}
                  onPressedChange={() =>
                    toggleToolbarFormat(editor, action.format)
                  }
                  pressed={formats[action.key]}
                  size="sm"
                >
                  <Icon />
                </Toggle>
              </ToolbarTooltip>
            );
          })}

          <Separator className="mx-0.5 h-5" orientation="vertical" />

          {/* Text color — uses `color` CSS property */}
          <ColorSwatches
            activeColor={formats.textColor}
            icon={BaselineIcon}
            label="Text color"
            onColorChange={(color) => applyTextColor(editor, color)}
            onOpenChange={handleSurfaceOpenChange}
          />

          {/* Background color — uses `background-color` CSS property */}
          <ColorSwatches
            activeColor={formats.bgColor}
            icon={PaintBucketIcon}
            label="Background color"
            onColorChange={(color) => applyBgColor(editor, color)}
            onOpenChange={handleSurfaceOpenChange}
          />

          <Separator className="mx-0.5 h-5" orientation="vertical" />

          <ToolbarTooltip label="Link">
            <Toggle
              aria-label="Link"
              onMouseDown={(event) => event.preventDefault()}
              onPressedChange={handleLinkToggle}
              pressed={formats.isLink}
              size="sm"
            >
              <LinkIcon />
            </Toggle>
          </ToolbarTooltip>

          <FloatingToolbarOverflowMenu
            editor={editor}
            formats={formats}
            onOpenChange={handleSurfaceOpenChange}
          />
        </TooltipProvider>
      </div>
    </div>,
    document.body
  );
}

import type { FloatingToolbarPosition } from "./types";

/** Minimum gap kept between the toolbar and the viewport edges. */
export const TOOLBAR_VIEWPORT_MARGIN = 8;

export interface ToolbarSize {
  height: number;
  width: number;
}

export interface ToolbarViewportSize {
  height: number;
  width: number;
}

/**
 * Keeps the selection-anchored toolbar fully inside the viewport. The
 * toolbar renders at the selection midpoint with `translate(-50%, -100%)`,
 * so its rendered box spans `[left - width/2, left + width/2]` horizontally
 * and `[top - height, top]` vertically. Without clamping, selections near
 * the browser edges push half the toolbar (or its full height) off screen.
 */
export const clampFloatingToolbarPosition = ({
  margin = TOOLBAR_VIEWPORT_MARGIN,
  position,
  toolbar,
  viewport,
}: {
  /** Gap between the toolbar and the viewport edge. */
  margin?: number;
  position: FloatingToolbarPosition;
  toolbar: ToolbarSize;
  viewport: ToolbarViewportSize;
}): FloatingToolbarPosition => {
  const halfWidth = toolbar.width / 2;
  const minLeft = halfWidth + margin;
  // When the viewport is narrower than the toolbar, both bounds collapse to
  // the left margin (best effort — the toolbar overflows either way).
  const maxLeft = Math.max(minLeft, viewport.width - halfWidth - margin);
  const minTop = toolbar.height + margin;

  return {
    left: Math.min(maxLeft, Math.max(minLeft, position.left)),
    top: Math.max(minTop, position.top),
  };
};

import { $isCodeNode } from "@lexical/code";
import { $isAutoLinkNode, $isLinkNode } from "@lexical/link";
import { $getSelectionStyleValueForProperty } from "@lexical/selection";
import { $getSelection, $isLineBreakNode, $isRangeSelection } from "lexical";
import type { LexicalNode, RangeSelection } from "lexical";

import { DEFAULT_FORMAT_STATE, EMPTY_TOOLBAR_POSITION } from "./constants";
import type {
  FloatingToolbarFormatState,
  FloatingToolbarPosition,
  FloatingToolbarState,
} from "./types";

export const areFloatingToolbarFormatsEqual = (
  left: FloatingToolbarFormatState,
  right: FloatingToolbarFormatState
) =>
  left.bgColor === right.bgColor &&
  left.isBold === right.isBold &&
  left.isCode === right.isCode &&
  left.isHighlight === right.isHighlight &&
  left.isItalic === right.isItalic &&
  left.isLink === right.isLink &&
  left.isStrikethrough === right.isStrikethrough &&
  left.isSubscript === right.isSubscript &&
  left.isSuperscript === right.isSuperscript &&
  left.isUnderline === right.isUnderline &&
  left.textColor === right.textColor;

export const areFloatingToolbarPositionsEqual = (
  left: FloatingToolbarPosition,
  right: FloatingToolbarPosition
) => left.left === right.left && left.top === right.top;

export const getFloatingToolbarSelectedNode = (selection: RangeSelection) => {
  const anchorNode = selection.anchor.getNode();
  const focusNode = selection.focus.getNode();

  if (anchorNode === focusNode) {
    return anchorNode;
  }

  return selection.isBackward() ? anchorNode : focusNode;
};

export const getSelectedLinkNode = (node: LexicalNode) => {
  const parent = node.getParent();

  if ($isLinkNode(parent) || $isAutoLinkNode(parent)) {
    return parent;
  }

  if ($isLinkNode(node) || $isAutoLinkNode(node)) {
    return node;
  }

  return null;
};

export const isSelectionWithinSingleLink = (selection: RangeSelection) => {
  const focusNode = getFloatingToolbarSelectedNode(selection);
  const focusLinkNode = getSelectedLinkNode(focusNode);

  if (!focusLinkNode) {
    return false;
  }

  const invalidNode = selection
    .getNodes()
    .filter((node) => !$isLineBreakNode(node))
    .find((node) => {
      const linkNode = getSelectedLinkNode(node);

      if (focusLinkNode && !focusLinkNode.is(linkNode)) {
        return true;
      }

      return $isAutoLinkNode(linkNode) && linkNode.getIsUnlinked();
    });

  return invalidNode === undefined;
};

const getToolbarPosition = (): FloatingToolbarPosition | null => {
  const nativeSelection = window.getSelection();
  if (!(nativeSelection && nativeSelection.rangeCount > 0)) {
    return null;
  }

  const range = nativeSelection.getRangeAt(0);
  const rectangle = range.getBoundingClientRect();

  if (rectangle.width === 0 && rectangle.height === 0) {
    return null;
  }

  return {
    left: rectangle.left + rectangle.width / 2,
    top: rectangle.top - 10,
  };
};

const getFormatState = (
  selection: RangeSelection,
  node: LexicalNode
): FloatingToolbarFormatState => {
  const linkNode = getSelectedLinkNode(node);

  return {
    bgColor: $getSelectionStyleValueForProperty(
      selection,
      "background-color",
      ""
    ),
    isBold: selection.hasFormat("bold"),
    isCode: selection.hasFormat("code"),
    isHighlight: selection.hasFormat("highlight"),
    isItalic: selection.hasFormat("italic"),
    isLink: linkNode !== null,
    isStrikethrough: selection.hasFormat("strikethrough"),
    isSubscript: selection.hasFormat("subscript"),
    isSuperscript: selection.hasFormat("superscript"),
    isUnderline: selection.hasFormat("underline"),
    textColor: $getSelectionStyleValueForProperty(selection, "color", ""),
  };
};

/**
 * Reads inline format state at the current cursor or selection without any
 * visibility or position checks. Intended for static (non-floating) toolbars
 * that always need to reflect the current editor state.
 */
export const readInlineFormats = (): FloatingToolbarFormatState => {
  const selection = $getSelection();
  if (!$isRangeSelection(selection)) {
    return DEFAULT_FORMAT_STATE;
  }

  const node = getFloatingToolbarSelectedNode(selection);
  return getFormatState(selection, node);
};

export const readFloatingToolbarState = (): FloatingToolbarState => {
  const selection = $getSelection();
  if (!($isRangeSelection(selection) && !selection.isCollapsed())) {
    return {
      formats: DEFAULT_FORMAT_STATE,
      isVisible: false,
      linkUrl: "",
      position: EMPTY_TOOLBAR_POSITION,
    };
  }

  const node = getFloatingToolbarSelectedNode(selection);
  const parent = node.getParent();
  const isInsideCodeBlock =
    $isCodeNode(node) || (parent && $isCodeNode(parent));

  if (isInsideCodeBlock) {
    return {
      formats: DEFAULT_FORMAT_STATE,
      isVisible: false,
      linkUrl: "",
      position: EMPTY_TOOLBAR_POSITION,
    };
  }

  const position = getToolbarPosition();
  if (!position) {
    return {
      formats: DEFAULT_FORMAT_STATE,
      isVisible: false,
      linkUrl: "",
      position: EMPTY_TOOLBAR_POSITION,
    };
  }

  const linkNode = isSelectionWithinSingleLink(selection)
    ? getSelectedLinkNode(node)
    : null;

  return {
    formats: getFormatState(selection, node),
    isVisible: true,
    linkUrl: linkNode?.getURL() ?? "",
    position,
  };
};

export interface FloatingToolbarFormatState {
  /** Current background-color CSS value of the selection, or "" if none/mixed. */
  bgColor: string;
  isBold: boolean;
  isCode: boolean;
  isHighlight: boolean;
  isItalic: boolean;
  isLink: boolean;
  isStrikethrough: boolean;
  isSubscript: boolean;
  isSuperscript: boolean;
  isUnderline: boolean;
  /** Current color CSS value of the selection, or "" if none/mixed. */
  textColor: string;
}

export interface FloatingToolbarPosition {
  left: number;
  top: number;
}

export interface FloatingToolbarState {
  formats: FloatingToolbarFormatState;
  isVisible: boolean;
  linkUrl: string;
  position: FloatingToolbarPosition;
}

