import type { FullToolbarUiAction, FullToolbarUiState } from "./types";

export const fullToolbarUiReducer = (
  state: FullToolbarUiState,
  action: FullToolbarUiAction
): FullToolbarUiState => {
  switch (action.type) {
    case "set-active-insert-index": {
      return state.activeInsertIndex === action.payload
        ? state
        : { ...state, activeInsertIndex: action.payload };
    }
    case "set-insert-open": {
      return {
        ...state,
        activeInsertIndex:
          action.payload.activeInsertIndex ?? state.activeInsertIndex,
        insertOpen: action.payload.open,
      };
    }
    default: {
      return state;
    }
  }
};

export interface FullToolbarUiState {
  activeInsertIndex: number;
  insertOpen: boolean;
}

export type FullToolbarUiAction =
  | { type: "set-active-insert-index"; payload: number }
  | {
      type: "set-insert-open";
      payload: { activeInsertIndex?: number; open: boolean };
    };

export const INITIAL_UI_STATE: FullToolbarUiState = {
  activeInsertIndex: 0,
  insertOpen: false,
};

"use client";

import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext";
import { mergeRegister } from "@lexical/utils";
import { COMMAND_PRIORITY_LOW, SELECTION_CHANGE_COMMAND } from "lexical";
import { useEffect, useState } from "react";

import type { BlockTypeValue } from "../block-type-toolbar/types";
import { getBlockTypeFromSelection } from "../block-type-toolbar/utils";
import { DEFAULT_FORMAT_STATE } from "../floating-toolbar/constants";
import {
  areFloatingToolbarFormatsEqual,
  readInlineFormats,
} from "../floating-toolbar/selection";
import type { FloatingToolbarFormatState } from "../floating-toolbar/types";

export function useToolbarState() {
  const [editor] = useLexicalComposerContext();
  const [blockType, setBlockType] = useState<BlockTypeValue>("paragraph");
  const [formats, setFormats] =
    useState<FloatingToolbarFormatState>(DEFAULT_FORMAT_STATE);

  useEffect(() => {
    const update = () => {
      editor.getEditorState().read(() => {
        const nextBlockType = getBlockTypeFromSelection();
        const resolvedBlockType = nextBlockType ?? "paragraph";

        setBlockType((currentBlockType) =>
          currentBlockType === resolvedBlockType
            ? currentBlockType
            : resolvedBlockType
        );

        const nextFormats = readInlineFormats();
        setFormats((currentFormats) =>
          areFloatingToolbarFormatsEqual(currentFormats, nextFormats)
            ? currentFormats
            : nextFormats
        );
      });
    };

    update();

    return mergeRegister(
      editor.registerCommand(
        SELECTION_CHANGE_COMMAND,
        () => {
          update();
          return false;
        },
        COMMAND_PRIORITY_LOW
      ),
      editor.registerUpdateListener(() => {
        update();
      })
    );
  }, [editor]);

  return { blockType, formats, setBlockType };
}

import { createLinkMatcherWithRegExp } from "@lexical/react/LexicalAutoLinkPlugin";

const URL_MATCHER_PATTERN =
  /(?<url>(?<scheme>https?:\/\/|www\.)[^\s<]+[^<.,:;"')\]\s])/iu;
const EMAIL_MATCHER_PATTERN =
  /(?<email>(?<emailAddress>[\w.+-]+@[\w-]+\.[\w.-]+))/iu;

const normalizeMatchedUrl = (text: string): string =>
  text.startsWith("http") ? text : `https://${text}`;

const normalizeMatchedEmail = (text: string): string => `mailto:${text}`;

export const AUTO_LINK_MATCHERS = [
  createLinkMatcherWithRegExp(URL_MATCHER_PATTERN, normalizeMatchedUrl),
  createLinkMatcherWithRegExp(EMAIL_MATCHER_PATTERN, normalizeMatchedEmail),
];

