import type { LexicalEditor } from "lexical";
import { $getSelection, $isNodeSelection, $isRangeSelection } from "lexical";

import {
  getFloatingToolbarSelectedNode,
  getSelectedLinkNode,
  isSelectionWithinSingleLink,
} from "../floating-toolbar/selection";

/**
 * A plain selection rectangle (floating-ui `ClientRectObject` shape) used as
 * the virtual anchor of the link popover. Snapshotting the fields keeps the
 * reducer state serializable and the popover re-derives it on scroll/resize.
 */
export interface FloatingLinkEditorAnchor {
  bottom: number;
  height: number;
  left: number;
  right: number;
  top: number;
  width: number;
  x: number;
  y: number;
}

const toAnchor = (rect: DOMRect): FloatingLinkEditorAnchor => ({
  bottom: rect.bottom,
  height: rect.height,
  left: rect.left,
  right: rect.right,
  top: rect.top,
  width: rect.width,
  x: rect.x,
  y: rect.y,
});

/**
 * Snapshots a DOM rect into the serializable anchor shape. Used both by the
 * selection anchor reader and by the hover-driven preview chip.
 */
export const toFloatingLinkEditorAnchor = toAnchor;

/**
 * Resolves the rectangle the link popover anchors to: the exact range rect
 * when text is selected, the caret line's text span when collapsed, and the
 * node element for node selections. Returns `null` when the native selection
 * is unavailable (e.g. a focus transition outside the editor).
 */
export const getLinkEditorAnchor = (
  editor: LexicalEditor
): FloatingLinkEditorAnchor | null => {
  const selection = $getSelection();
  const nativeSelection = window.getSelection();
  const rootElement = editor.getRootElement();

  if (!(selection && rootElement && editor.isEditable())) {
    return null;
  }

  let rectangle: DOMRect | null = null;

  if ($isNodeSelection(selection)) {
    const [node] = selection.getNodes();
    const element = node ? editor.getElementByKey(node.getKey()) : null;
    rectangle = element?.getBoundingClientRect() ?? null;
  } else if (
    nativeSelection &&
    nativeSelection.rangeCount > 0 &&
    rootElement.contains(nativeSelection.anchorNode)
  ) {
    rectangle = nativeSelection.isCollapsed
      ? (nativeSelection.focusNode?.parentElement?.getBoundingClientRect() ??
        nativeSelection.getRangeAt(0).getBoundingClientRect())
      : nativeSelection.getRangeAt(0).getBoundingClientRect();
  }

  return rectangle ? toAnchor(rectangle) : null;
};

export const readSelectedLinkUrl = () => {
  const selection = $getSelection();

  if ($isRangeSelection(selection)) {
    if (!isSelectionWithinSingleLink(selection)) {
      return "";
    }

    return (
      getSelectedLinkNode(
        getFloatingToolbarSelectedNode(selection)
      )?.getURL() ?? ""
    );
  }

  if ($isNodeSelection(selection)) {
    const [node] = selection.getNodes();
    return node ? (getSelectedLinkNode(node)?.getURL() ?? "") : "";
  }

  return "";
};

export const readSelectedLinkText = () => {
  const selection = $getSelection();

  if ($isRangeSelection(selection)) {
    if (!isSelectionWithinSingleLink(selection)) {
      return "";
    }

    return (
      getSelectedLinkNode(
        getFloatingToolbarSelectedNode(selection)
      )?.getTextContent() ?? ""
    );
  }

  if ($isNodeSelection(selection)) {
    const [node] = selection.getNodes();
    return node ? (getSelectedLinkNode(node)?.getTextContent() ?? "") : "";
  }

  return "";
};

export const selectionContainsLink = () => {
  const selection = $getSelection();

  if ($isRangeSelection(selection)) {
    return isSelectionWithinSingleLink(selection);
  }

  if ($isNodeSelection(selection)) {
    const [node] = selection.getNodes();
    return Boolean(node && getSelectedLinkNode(node));
  }

  return false;
};

export const isSameLinkEditorAnchor = (
  current: FloatingLinkEditorAnchor | null,
  next: FloatingLinkEditorAnchor
): boolean =>
  current !== null &&
  current.left === next.left &&
  current.top === next.top &&
  current.width === next.width &&
  current.height === next.height;

import type { FloatingLinkEditorAnchor } from "./floating-link-editor-position";
import { isSameLinkEditorAnchor } from "./floating-link-editor-position";
import { LINK_PLACEHOLDER_URL } from "./utils";

/**
 * Which surface the plugin renders:
 * - `closed` — nothing
 * - `preview` — the Google-Docs-style hover chip (label + Edit)
 * - `edit` — the full editing card
 *
 * The chip is purely hover-driven: a click that merely places the caret
 * inside a link never opens anything. The card opens only through an
 * explicit action (chip Edit, toolbar link button, Cmd/Ctrl+K).
 */
export type FloatingLinkEditorSurface = "closed" | "edit" | "preview";

/** The hovered link: its meta and rect, kept so the chip survives re-syncs. */
export interface FloatingLinkPreviewTarget {
  anchor: FloatingLinkEditorAnchor;
  linkKey: string;
  linkText: string;
  linkUrl: string;
}

export interface FloatingLinkEditorState {
  anchor: FloatingLinkEditorAnchor | null;
  editedLinkText: string;
  editedLinkUrl: string;
  hoverTarget: FloatingLinkPreviewTarget | null;
  isLink: boolean;
  isLinkEditMode: boolean;
  linkText: string;
  linkUrl: string;
  surface: FloatingLinkEditorSurface;
}

export type FloatingLinkEditorAction =
  | {
      type: "sync";
      payload: {
        anchor: FloatingLinkEditorAnchor | null;
        isLink: boolean;
        linkText: string;
        linkUrl: string;
      };
    }
  | { type: "hover-link"; payload: FloatingLinkPreviewTarget }
  | { type: "unhover-link" }
  | {
      type: "open-edit-mode";
      payload?: {
        editedLinkText?: string;
        editedLinkUrl?: string;
      };
    }
  | { type: "close-link-editor" }
  | { type: "set-edited-link-text"; payload: string }
  | { type: "set-edited-link-url"; payload: string };

export const FLOATING_LINK_EDITOR_INITIAL_STATE: FloatingLinkEditorState = {
  anchor: null,
  editedLinkText: "",
  editedLinkUrl: LINK_PLACEHOLDER_URL,
  hoverTarget: null,
  isLink: false,
  isLinkEditMode: false,
  linkText: "",
  linkUrl: "",
  surface: "closed",
};

const keepHoverChip = (
  state: FloatingLinkEditorState,
  linkText: string,
  linkUrl: string
): FloatingLinkEditorState => ({
  ...state,
  anchor: state.anchor,
  isLink: false,
  linkText,
  linkUrl,
  surface: "preview",
});

const closeEverySurface = (
  state: FloatingLinkEditorState,
  payload: { isLink: boolean; linkText: string; linkUrl: string }
): FloatingLinkEditorState => ({
  ...state,
  anchor: null,
  isLink: payload.isLink,
  isLinkEditMode: false,
  linkText: payload.linkText,
  linkUrl: payload.linkUrl,
  surface: "closed",
});

const keepOpenSurface = (
  state: FloatingLinkEditorState,
  nextAnchor: FloatingLinkEditorAnchor,
  payload: Extract<FloatingLinkEditorAction, { type: "sync" }>["payload"]
): FloatingLinkEditorState => ({
  ...state,
  anchor: nextAnchor,
  editedLinkText: state.isLinkEditMode
    ? state.editedLinkText
    : payload.linkText,
  editedLinkUrl: state.isLinkEditMode
    ? state.editedLinkUrl
    : payload.linkUrl || LINK_PLACEHOLDER_URL,
  isLink: true,
  isLinkEditMode: state.isLinkEditMode,
  linkText: payload.linkText,
  linkUrl: payload.linkUrl,
  surface:
    state.isLinkEditMode || state.surface === "edit" ? "edit" : state.surface,
});

const isEditSurface = (state: FloatingLinkEditorState): boolean =>
  state.isLinkEditMode || state.surface === "edit";

const applySyncAction = (
  state: FloatingLinkEditorState,
  payload: Extract<FloatingLinkEditorAction, { type: "sync" }>["payload"]
): FloatingLinkEditorState => {
  const { anchor, isLink, linkText, linkUrl } = payload;

  // The selection itself carries no link anymore: the edit card dies with
  // it, but a live hover chip is caret-independent and survives — the
  // pointer's link is separate from the selection.
  if (!isLink) {
    if (state.surface === "preview" && !isEditSurface(state)) {
      return keepHoverChip(state, linkText, linkUrl);
    }

    return closeEverySurface(state, { isLink, linkText, linkUrl });
  }

  // The anchor reads the native selection, which is momentarily unavailable
  // during focus transitions (e.g. a toolbar mousedown) right after an
  // explicit open. Keep the last known anchor so the popover is not dropped
  // before the user types; a null anchor with no open surface is just a
  // closed state.
  if (anchor === null) {
    if (!isEditSurface(state)) {
      return closeEverySurface(state, { isLink, linkText, linkUrl });
    }

    return state.anchor === null
      ? closeEverySurface(state, { isLink, linkText, linkUrl })
      : keepOpenSurface(state, state.anchor, payload);
  }

  const nextAnchor =
    state.anchor !== null && isSameLinkEditorAnchor(state.anchor, anchor)
      ? state.anchor
      : anchor;

  return keepOpenSurface(state, nextAnchor, payload);
};

const applyHoverLink = (
  state: FloatingLinkEditorState,
  payload: FloatingLinkPreviewTarget
): FloatingLinkEditorState => {
  // The edit card owns the pointer's attention — hovering another link
  // must not pop a chip over it. Re-hovering the same link is a no-op
  // (identical state) so pointerover bursts don't loop re-renders.
  const isSameTarget =
    state.hoverTarget !== null &&
    state.hoverTarget.linkKey === payload.linkKey &&
    isSameLinkEditorAnchor(state.hoverTarget.anchor, payload.anchor);

  if (state.isLinkEditMode || isSameTarget) {
    return state;
  }

  return {
    ...state,
    anchor: payload.anchor,
    editedLinkText: payload.linkText,
    editedLinkUrl: payload.linkUrl || LINK_PLACEHOLDER_URL,
    hoverTarget: payload,
    surface: "preview",
  };
};

const applyUnhoverLink = (
  state: FloatingLinkEditorState
): FloatingLinkEditorState => {
  if (state.hoverTarget === null) {
    return state;
  }

  // In edit mode the card is not hover-driven: a stray pointer leave (the
  // chip unmounting after the Edit click, the grace timer expiring while the
  // pointer rests outside the card) must not touch the card — clearing the
  // anchor here unmounted the card while `isLinkEditMode` stayed true, and
  // `applyHoverLink` then swallowed every later hover forever.
  if (state.isLinkEditMode) {
    return { ...state, hoverTarget: null };
  }

  return {
    ...state,
    anchor: null,
    hoverTarget: null,
    surface: "closed",
  };
};

export const floatingLinkEditorReducer = (
  state: FloatingLinkEditorState,
  action: FloatingLinkEditorAction
): FloatingLinkEditorState => {
  switch (action.type) {
    case "sync": {
      return applySyncAction(state, action.payload);
    }
    case "hover-link": {
      return applyHoverLink(state, action.payload);
    }
    case "unhover-link": {
      return applyUnhoverLink(state);
    }
    case "open-edit-mode": {
      return {
        ...state,
        editedLinkText: action.payload?.editedLinkText ?? state.linkText,
        editedLinkUrl:
          action.payload?.editedLinkUrl ??
          (state.linkUrl || LINK_PLACEHOLDER_URL),
        isLinkEditMode: true,
        surface: "edit",
      };
    }
    case "close-link-editor": {
      return state.isLink || state.isLinkEditMode
        ? {
            ...state,
            anchor: null,
            hoverTarget: null,
            isLink: false,
            isLinkEditMode: false,
            surface: "closed",
          }
        : state;
    }
    case "set-edited-link-text": {
      return state.editedLinkText === action.payload
        ? state
        : { ...state, editedLinkText: action.payload };
    }
    case "set-edited-link-url": {
      return state.editedLinkUrl === action.payload
        ? state
        : { ...state, editedLinkUrl: action.payload };
    }
    default: {
      return state;
    }
  }
};

"use client";

import { $isLinkNode } from "@lexical/link";
import { $findMatchingParent } from "@lexical/utils";
import { $getNodeByKey } from "lexical";
import type { LexicalEditor } from "lexical";
import type { Dispatch } from "react";

import { HoverCard, HoverCardContent } from "@/components/ui/hover-card";
import { Popover, PopoverContent } from "@/components/ui/popover";

import { FloatingLinkEditorPanel } from "./floating-link-editor-panel";
import type {
  FloatingLinkEditorAction,
  FloatingLinkEditorState,
} from "./floating-link-editor-reducer";
import { FloatingLinkPreviewChip } from "./floating-link-preview-chip";
import { LINK_PLACEHOLDER_URL, sanitizeEditorLinkUrl } from "./utils";

interface FloatingLinkEditorSurfacesProps {
  anchorElement: { getBoundingClientRect: () => DOMRect } | null;
  dispatch: Dispatch<FloatingLinkEditorAction>;
  editor: LexicalEditor;
  onInputRef: (element: HTMLInputElement | null) => void;
  onPointerOverChipChange: (isOver: boolean) => void;
  state: FloatingLinkEditorState;
}

/**
 * The two renderable states of the floating link editor: the hover preview
 * chip (caret-independent, pointer-driven) and the edit card (explicitly
 * opened via chip Edit, toolbar button or Cmd/Ctrl+K). Mounting and
 * anchoring decisions stay in the plugin component.
 */
export function FloatingLinkEditorSurfaces({
  anchorElement,
  dispatch,
  editor,
  onInputRef,
  onPointerOverChipChange,
  state,
}: FloatingLinkEditorSurfacesProps) {
  const {
    anchor: _anchor,
    editedLinkText,
    editedLinkUrl,
    hoverTarget,
    isLinkEditMode,
    linkUrl,
    surface,
  } = state;

  if (anchorElement === null) {
    return null;
  }

  if (surface === "preview" && hoverTarget !== null) {
    // HoverCard (Base UI preview card) is the purpose-built surface for
    // pointer previews: it keeps hover intent, Escape and outside press
    // dismissal native. Open state stays controlled — the link lives inside
    // Lexical-owned DOM, so hover detection stays with the plugin.
    return (
      <HoverCard
        onOpenChange={(nextOpen) => {
          if (!nextOpen) {
            dispatch({ type: "unhover-link" });
          }
        }}
        open
      >
        <HoverCardContent
          align="start"
          anchor={anchorElement}
          className="editor-floating editor-floating-no-ring editor-floating-padding-sm w-72 max-w-[calc(100vw-2rem)] border border-border"
          onPointerEnter={() => onPointerOverChipChange(true)}
          onPointerLeave={() => onPointerOverChipChange(false)}
          side="bottom"
          sideOffset={6}
        >
          <FloatingLinkPreviewChip
            href={sanitizeEditorLinkUrl(hoverTarget.linkUrl)}
            label={hoverTarget.linkText}
            onEdit={() => {
              // Selecting the link first mirrors the reference flow and lets
              // the selection sync carry the card: an open edit card whose
              // selection lives elsewhere dies on the next sync.
              editor.update(() => {
                const node = $getNodeByKey(hoverTarget.linkKey);
                if (node === null) {
                  return;
                }
                const linkNode = $findMatchingParent(node, $isLinkNode);
                linkNode?.select();
              });
              dispatch({
                payload: {
                  editedLinkText: hoverTarget.linkText,
                  editedLinkUrl: hoverTarget.linkUrl || LINK_PLACEHOLDER_URL,
                },
                type: "open-edit-mode",
              });
            }}
          />
        </HoverCardContent>
      </HoverCard>
    );
  }

  return (
    <Popover
      modal
      onOpenChange={(nextOpen) => {
        if (!nextOpen) {
          // The card is always opened explicitly (chip Edit, toolbar
          // button, Cmd/Ctrl+K), so any dismissal is a real close request.
          dispatch({ type: "close-link-editor" });
        }
      }}
      open
    >
      <PopoverContent
        align="start"
        anchor={anchorElement}
        className="editor-floating editor-floating-padding-md max-w-[calc(100vw-2rem)]"
        data-floating-link-card
        initialFocus={false}
        side="bottom"
        sideOffset={6}
      >
        <FloatingLinkEditorPanel
          editedLinkText={editedLinkText}
          editedLinkUrl={editedLinkUrl}
          editor={editor}
          inputRef={onInputRef}
          isLinkEditMode={isLinkEditMode}
          linkUrl={linkUrl}
          onEditedLinkTextChange={(value) =>
            dispatch({ payload: value, type: "set-edited-link-text" })
          }
          onEditedLinkUrlChange={(value) =>
            dispatch({ payload: value, type: "set-edited-link-url" })
          }
          onRequestClose={() => dispatch({ type: "close-link-editor" })}
        />
      </PopoverContent>
    </Popover>
  );
}

"use client";

import { $isLinkNode, TOGGLE_LINK_COMMAND } from "@lexical/link";
import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext";
import { $findMatchingParent, mergeRegister } from "@lexical/utils";
import {
  $getSelection,
  $isRangeSelection,
  CLICK_COMMAND,
  COMMAND_PRIORITY_HIGH,
  COMMAND_PRIORITY_LOW,
  KEY_DOWN_COMMAND,
  KEY_ESCAPE_COMMAND,
  SELECTION_CHANGE_COMMAND,
} from "lexical";
import { useEffect, useEffectEvent, useMemo, useReducer, useRef } from "react";

import { OPEN_FLOATING_LINK_EDITOR_COMMAND } from "../floating-toolbar/link-command";
import { getFloatingToolbarSelectedNode } from "../floating-toolbar/selection";
import {
  getLinkEditorAnchor,
  readSelectedLinkText,
  readSelectedLinkUrl,
  selectionContainsLink,
} from "./floating-link-editor-position";
import {
  FLOATING_LINK_EDITOR_INITIAL_STATE,
  floatingLinkEditorReducer,
} from "./floating-link-editor-reducer";
import { FloatingLinkEditorSurfaces } from "./floating-link-editor-surfaces";
import {
  getHoveredEditorLink,
  isInsideLinkSurface,
  readLinkElementAnchor,
} from "./floating-link-hover";
import { createHoverBridge } from "./floating-link-hover-bridge";
import { LINK_PLACEHOLDER_URL } from "./utils";

/** Grace period (ms) the pointer has to travel from link text into the chip. */
const HOVER_BRIDGE_DELAY_MS = 120;

export function FloatingLinkEditorPlugin() {
  const [editor] = useLexicalComposerContext();
  const animationFrameRef = useRef<number | null>(null);
  const [state, dispatch] = useReducer(
    floatingLinkEditorReducer,
    FLOATING_LINK_EDITOR_INITIAL_STATE
  );
  // Owns the hover grace timer. `dispatch` is stable across renders, so the
  // bridge is created once; the StrictMode double-mount reuses it after
  // cleanup disposed any pending timer.
  const hoverBridge = useMemo(
    () =>
      createHoverBridge({
        graceMs: HOVER_BRIDGE_DELAY_MS,
        onGraceExpired: () => dispatch({ type: "unhover-link" }),
      }),
    [dispatch]
  );
  const { anchor, hoverTarget, isLink, surface } = state;

  const updateLinkEditor = () => {
    const nextIsLink = selectionContainsLink();
    const nextLinkText = nextIsLink ? readSelectedLinkText() : "";
    const nextLinkUrl = nextIsLink ? readSelectedLinkUrl() : "";
    const nextAnchor = getLinkEditorAnchor(editor);

    dispatch({
      payload: {
        anchor: nextAnchor,
        isLink: nextIsLink,
        linkText: nextLinkText,
        linkUrl: nextLinkUrl,
      },
      type: "sync",
    });
  };

  const scheduleLinkEditorUpdate = useEffectEvent(() => {
    if (animationFrameRef.current !== null) {
      return;
    }

    animationFrameRef.current = window.requestAnimationFrame(() => {
      animationFrameRef.current = null;
      editor.getEditorState().read(() => {
        updateLinkEditor();
      });
    });
  });

  useEffect(
    () =>
      mergeRegister(
        editor.registerUpdateListener(() => {
          scheduleLinkEditorUpdate();
        }),
        editor.registerCommand(
          SELECTION_CHANGE_COMMAND,
          () => {
            scheduleLinkEditorUpdate();
            return false;
          },
          COMMAND_PRIORITY_LOW
        ),
        editor.registerCommand(
          OPEN_FLOATING_LINK_EDITOR_COMMAND,
          () => {
            dispatch({
              payload: {
                editedLinkText: readSelectedLinkText(),
                editedLinkUrl: readSelectedLinkUrl() || LINK_PLACEHOLDER_URL,
              },
              type: "open-edit-mode",
            });
            scheduleLinkEditorUpdate();
            return true;
          },
          COMMAND_PRIORITY_HIGH
        ),
        editor.registerCommand(
          KEY_DOWN_COMMAND,
          (event) => {
            const isModifierPressed = event.metaKey || event.ctrlKey;
            if (!(isModifierPressed && event.key.toLowerCase() === "k")) {
              return false;
            }

            event.preventDefault();

            if (selectionContainsLink()) {
              dispatch({ type: "close-link-editor" });
              editor.dispatchCommand(TOGGLE_LINK_COMMAND, null);
              return true;
            }

            dispatch({
              payload: { editedLinkUrl: LINK_PLACEHOLDER_URL },
              type: "open-edit-mode",
            });
            editor.dispatchCommand(TOGGLE_LINK_COMMAND, LINK_PLACEHOLDER_URL);
            return true;
          },
          COMMAND_PRIORITY_HIGH
        ),
        editor.registerCommand(
          KEY_ESCAPE_COMMAND,
          () => {
            if (!isLink) {
              return false;
            }

            dispatch({ type: "close-link-editor" });
            return true;
          },
          COMMAND_PRIORITY_HIGH
        ),
        editor.registerCommand(
          CLICK_COMMAND,
          (event) => {
            const selection = $getSelection();
            if (!$isRangeSelection(selection)) {
              return false;
            }

            const node = getFloatingToolbarSelectedNode(selection);
            const linkNode = $findMatchingParent(node, $isLinkNode);
            if ($isLinkNode(linkNode) && (event.metaKey || event.ctrlKey)) {
              window.open(linkNode.getURL(), "_blank", "noopener,noreferrer");
              return true;
            }

            return false;
          },
          COMMAND_PRIORITY_LOW
        )
      ),
    [editor, isLink]
  );

  // Owns the scheduled animation frame symmetrically: schedule on mount,
  // cancel AND clear on unmount. If the ref is left pointing at a cancelled
  // frame, StrictMode's double-mount poisons the early-return guard in
  // scheduleLinkEditorUpdate forever — syncs stop running and the editor
  // never detects a selected link.
  useEffect(() => {
    scheduleLinkEditorUpdate();
    return () => {
      if (animationFrameRef.current !== null) {
        window.cancelAnimationFrame(animationFrameRef.current);
        animationFrameRef.current = null;
      }
    };
  }, []);

  useEffect(() => {
    const handleWindowChange = () => {
      scheduleLinkEditorUpdate();
    };

    window.addEventListener("resize", handleWindowChange);
    window.addEventListener("scroll", handleWindowChange, true);

    return () => {
      window.removeEventListener("resize", handleWindowChange);
      window.removeEventListener("scroll", handleWindowChange, true);
    };
  }, []);

  // Hover wiring for the preview chip. The pointer's link is tracked on the
  // document — hover is independent of the selection, so a click that merely
  // places the caret inside a link never opens anything. `pointerover`
  // fires for every element the pointer crosses; links refresh the chip,
  // and leaving every link arms the grace-period dismissal. Re-entering a
  // link or the chip cancels that dismissal — the grace period is a bridge
  // for pointer travel, not an idle timeout over the link itself.
  useEffect(() => {
    const handlePointerOver = (event: PointerEvent) => {
      if (isInsideLinkSurface(event.target)) {
        hoverBridge.onSurface();
        return;
      }

      const hovered = getHoveredEditorLink(editor, event.target);
      if (hovered === null) {
        hoverBridge.onPlainContent();
        return;
      }

      const anchorRect = readLinkElementAnchor(hovered.linkElement);
      if (anchorRect === null) {
        dispatch({ type: "unhover-link" });
        return;
      }

      hoverBridge.onLink();
      dispatch({
        payload: {
          anchor: anchorRect,
          linkKey: hovered.linkKey,
          linkText: hovered.linkText,
          linkUrl: hovered.linkUrl,
        },
        type: "hover-link",
      });
    };

    document.addEventListener("pointerover", handlePointerOver, true);
    return () => {
      document.removeEventListener("pointerover", handlePointerOver, true);
      hoverBridge.dispose();
    };
  }, [editor, hoverBridge]);

  // Keep the chip's anchor glued to the hovered link: re-read the rect
  // whenever the hover target changes. The element map lookup dies with
  // late mutations, and a zero-size rect dispatches unhover.
  useEffect(() => {
    if (hoverTarget === null) {
      return;
    }

    const linkElement = editor.getElementByKey(hoverTarget.linkKey);
    if (!(linkElement instanceof HTMLAnchorElement)) {
      dispatch({ type: "unhover-link" });
      return;
    }

    const anchorRect = readLinkElementAnchor(linkElement);
    if (anchorRect === null) {
      dispatch({ type: "unhover-link" });
      return;
    }

    dispatch({
      payload: {
        anchor: anchorRect,
        linkKey: hoverTarget.linkKey,
        linkText: hoverTarget.linkText,
        linkUrl: hoverTarget.linkUrl,
      },
      type: "hover-link",
    });
  }, [editor, hoverTarget]);

  const handleInputRef = (element: HTMLInputElement | null) => {
    if (!(element && state.isLinkEditMode)) {
      return;
    }

    element.focus();
    element.select();
  };

  const handlePointerOverChipChange = (isOver: boolean) => {
    if (isOver) {
      hoverBridge.onSurface();
      return;
    }

    dispatch({ type: "unhover-link" });
  };

  // Virtual anchor (floating-ui) around the live surface rect: the chip
  // anchors to the hovered link, the card to the edit surface. Base UI
  // re-measures it on scroll/resize; refresh effects above keep it fresh.
  // A real DOMRect (not a plain lookalike) satisfies the popover's anchor
  // contract, `toJSON` included.
  const anchorElement = useMemo(
    () =>
      anchor === null
        ? null
        : {
            getBoundingClientRect: () =>
              new DOMRect(anchor.left, anchor.top, anchor.width, anchor.height),
          },
    [anchor]
  );

  if (surface === "closed" || anchorElement === null) {
    return null;
  }

  return (
    <FloatingLinkEditorSurfaces
      anchorElement={anchorElement}
      dispatch={dispatch}
      editor={editor}
      onInputRef={handleInputRef}
      onPointerOverChipChange={handlePointerOverChipChange}
      state={state}
    />
  );
}

/**
 * The hover chip's dismissal bridge. The pointer can travel from link text
 * into the chip (or back into a link), so leaving a link must not dismiss
 * the chip outright — a grace-period timer gives the pointer that window.
 *
 * The bridge owns three pointer facts and one timer:
 * - over a link → the bridge succeeded, any pending dismissal is cancelled
 * - over a chip/card surface → those surfaces own their own dismissal, any
 *   pending dismissal is cancelled
 * - over plain (non-link) content → arm the grace-period dismissal
 *
 * The timer is armed at most once and only ever fires while the pointer is
 * over plain content — re-entering a link or a surface always cancels it.
 * (Bug fixed here: the timer used to survive link re-entry and kill a freshly
 * opened chip mid-hover, which made the first mouse pass unreliable.)
 */
export interface HoverBridgeDeps {
  /** Dispatched when the grace period expires over plain content. */
  onGraceExpired: () => void;
  /** Grace period in ms the pointer has to reach a link or the chip. */
  graceMs: number;
  /** Injectable scheduler (defaults to window timers); lets tests advance time. */
  schedule?: (callback: () => void, ms: number) => number;
  cancel?: (timerId: number) => void;
}

export interface HoverBridge {
  /** Pointer is over a link: cancel any pending grace dismissal. */
  onLink: () => void;
  /** Pointer is over a chip/card surface: cancel any pending grace dismissal. */
  onSurface: () => void;
  /** Pointer is over plain content: arm the grace-period dismissal. */
  onPlainContent: () => void;
  /** Cancel the timer without firing; used on unmount. */
  dispose: () => void;
}

const defaultSchedule =
  typeof window === "undefined"
    ? undefined
    : (callback: () => void, ms: number) => window.setTimeout(callback, ms);
const defaultCancel =
  typeof window === "undefined"
    ? undefined
    : (timerId: number) => window.clearTimeout(timerId);

export const createHoverBridge = ({
  onGraceExpired,
  graceMs,
  schedule = defaultSchedule,
  cancel = defaultCancel,
}: HoverBridgeDeps): HoverBridge => {
  let timerId: number | null = null;

  const cancelPending = () => {
    if (timerId !== null && cancel) {
      cancel(timerId);
    }
    timerId = null;
  };

  const arm = () => {
    if (timerId !== null || !schedule) {
      return;
    }

    timerId = schedule(() => {
      timerId = null;
      onGraceExpired();
    }, graceMs);
  };

  return {
    dispose: cancelPending,
    onLink: cancelPending,
    onPlainContent: arm,
    onSurface: cancelPending,
  };
};

import { $isLinkNode } from "@lexical/link";
import { $findMatchingParent } from "@lexical/utils";
import type { LexicalEditor } from "lexical";
import { $getNearestNodeFromDOMNode } from "lexical";

import type { FloatingLinkEditorAnchor } from "./floating-link-editor-position";
import { toFloatingLinkEditorAnchor } from "./floating-link-editor-position";

/** Hovered floating surfaces that keep the preview chip alive. */
const LINK_SURFACE_SELECTOR =
  '[data-slot="floating-link-preview"], [data-floating-link-card]';

export interface HoveredEditorLink {
  linkElement: HTMLAnchorElement;
  linkKey: string;
  linkText: string;
  linkUrl: string;
}

/**
 * True when the pointer moved over the preview chip itself. Hovering the
 * chip must not re-trigger detection (the chip floats over the link text,
 * so `pointerover` fires on it constantly).
 */
export const isInsideLinkSurface = (eventTarget: EventTarget | null): boolean =>
  eventTarget instanceof Element &&
  eventTarget.closest(LINK_SURFACE_SELECTOR) !== null;

/**
 * Snapshots the hovered link's rect. Re-running this on every hover tick
 * keeps the chip glued to the link while it reflows. A zero-size rect means
 * the element is dead (e.g. its text was wiped) and the chip must go.
 */
export const readLinkElementAnchor = (
  linkElement: Element
): FloatingLinkEditorAnchor | null => {
  const rect = linkElement.getBoundingClientRect();
  return rect.width === 0 && rect.height === 0
    ? null
    : toFloatingLinkEditorAnchor(rect);
};

const readLinkNodeMeta = (
  editor: LexicalEditor,
  linkElement: HTMLAnchorElement
): { key: string; text: string; url: string } | null => {
  let meta: { key: string; text: string; url: string } | null = null;

  // `editor.read` (not `getEditorState().read`) — the DOM→node lookup needs
  // this editor registered as the active editor for the duration of the call.
  editor.read(() => {
    const node = $getNearestNodeFromDOMNode(linkElement);
    if (node === null) {
      return;
    }
    const linkNode = $findMatchingParent(node, $isLinkNode);
    if (!$isLinkNode(linkNode)) {
      return;
    }

    meta = {
      key: linkNode.getKey(),
      text: linkNode.getTextContent(),
      url: linkNode.getURL(),
    };
  });

  return meta;
};

const getHoveredLinkFromElement = (
  editor: LexicalEditor,
  linkElement: HTMLAnchorElement
): HoveredEditorLink | null => {
  const rootElement = editor.getRootElement();
  if (!rootElement?.contains(linkElement)) {
    return null;
  }

  const meta = readLinkNodeMeta(editor, linkElement);
  return meta
    ? {
        linkElement,
        linkKey: meta.key,
        linkText: meta.text,
        linkUrl: meta.url,
      }
    : null;
};

/**
 * Resolves the link under a pointer event target. Hover is independent of
 * the selection: a collapsed caret inside a link plus the pointer elsewhere
 * must NOT pop the chip — only the pointer's link matters. Anchors outside
 * this editor's root (demo chrome, other editors) resolve to `null`.
 */
export const getHoveredEditorLink = (
  editor: LexicalEditor,
  eventTarget: EventTarget | null
): HoveredEditorLink | null => {
  if (!(eventTarget instanceof Element)) {
    return null;
  }

  // Over the chip itself: the chip's own pointer handlers own dismissal —
  // element detection here would re-target with a stale rect instead.
  if (isInsideLinkSurface(eventTarget)) {
    return null;
  }

  const linkElement = eventTarget.closest("a");
  return linkElement instanceof HTMLAnchorElement
    ? getHoveredLinkFromElement(editor, linkElement)
    : null;
};

