export interface SlashCommandPluginProps {
  /**
   * Resolved slash-menu contributions: the core block types plus every entry
   * contributed by installed feature descriptors. The composition surface
   * builds this list — the menu renders exactly what it receives.
   */
  commands: readonly FeatureSlashCommand[];
}

interface SlashCommandState {
  isOpen: boolean;
  query: string;
  rawSelectedCommandId: SlashCommandSelection;
}

type SlashCommandAction =
  | { type: "patch"; payload: Partial<SlashCommandState> }
  | {
      type: "move-selected-command";
      payload: {
        commands: readonly SlashCommand[];
        direction: "down" | "up";
      };
    };

const createInitialSlashCommandState = (
  rawSelectedCommandId: SlashCommandSelection
): SlashCommandState => ({
  isOpen: false,
  query: "",
  rawSelectedCommandId,
});

const applySlashCommandPatch = (
  state: SlashCommandState,
  patch: Partial<SlashCommandState>
): SlashCommandState => {
  for (const key of Object.keys(patch) as (keyof SlashCommandState)[]) {
    if (state[key] !== patch[key]) {
      return { ...state, ...patch };
    }
  }

  return state;
};

const slashCommandReducer = (
  state: SlashCommandState,
  action: SlashCommandAction
): SlashCommandState => {
  switch (action.type) {
    case "patch": {
      return applySlashCommandPatch(state, action.payload);
    }
    case "move-selected-command": {
      return applySlashCommandPatch(state, {
        rawSelectedCommandId: getNeighborCommandId(
          action.payload.commands,
          state.rawSelectedCommandId,
          action.payload.direction
        ),
      });
    }
    default: {
      return state;
    }
  }
};

export function SlashCommandPlugin({ commands }: SlashCommandPluginProps) {
  const [editor] = useLexicalComposerContext();
  const [state, dispatch] = useReducer(
    slashCommandReducer,
    getFirstCommandId(commands.map((entry) => entry.command)),
    createInitialSlashCommandState
  );
  const { isOpen, query, rawSelectedCommandId } = state;
  const commandListRef = useRef<HTMLDivElement | null>(null);
  const animationFrameRef = useRef<number | null>(null);
  const lastPointerPositionRef = useRef<{ x: number; y: number } | null>(null);

  const filteredCommands = filterSlashCommands(
    commands.map((entry) => entry.command),
    query
  );
  const filteredEntries = commands.filter((entry) =>
    filteredCommands.some((command) => command.id === entry.command.id)
  );

  const selectedCommandId: SlashCommandSelection = (() => {
    if (filteredCommands.length === 0) {
      return "";
    }

    return hasSelectedCommand(filteredCommands, rawSelectedCommandId)
      ? rawSelectedCommandId
      : getFirstCommandId(filteredCommands);
  })();

  const selectedIndex = getSelectedCommandIndex(
    filteredCommands,
    selectedCommandId
  );

  // The menu is only actually visible when the popover renders content;
  // key handling and scroll-into-view must match this exactly.
  const isMenuVisible = isOpen && filteredCommands.length > 0;

  const anchor = createSlashMenuAnchor(editor);

  const updateSlashMenu = () => {
    const selection = $getSelection();
    const isCollapsedRangeSelection =
      $isRangeSelection(selection) && selection.isCollapsed();

    if (!isCollapsedRangeSelection) {
      dispatch({ payload: { isOpen: false }, type: "patch" });
      return;
    }

    const node = selection.anchor.getNode();
    if (!$isTextNode(node)) {
      dispatch({ payload: { isOpen: false }, type: "patch" });
      return;
    }

    const textUpToCursor = node
      .getTextContent()
      .slice(0, selection.anchor.offset);
    const nextQuery = getSlashQueryMatch(textUpToCursor);

    if (nextQuery === null) {
      dispatch({ payload: { isOpen: false }, type: "patch" });
      return;
    }

    if (!getSelectionRectangle(editor)) {
      dispatch({ payload: { isOpen: false }, type: "patch" });
      return;
    }

    dispatch({
      payload: { isOpen: true, query: nextQuery },
      type: "patch",
    });
  };

  const scheduleSlashMenuUpdate = useEffectEvent(() => {
    if (animationFrameRef.current !== null) {
      return;
    }

    animationFrameRef.current = window.requestAnimationFrame(() => {
      animationFrameRef.current = null;
      editor.getEditorState().read(() => {
        updateSlashMenu();
      });
    });
  });

  const executeEntry = useEffectEvent((entry: FeatureSlashCommand) => {
    dispatch({ payload: { isOpen: false }, type: "patch" });
    entry.run(editor);
  });

  useEffect(() => {
    if (!isMenuVisible) {
      return;
    }

    const animationFrameId = window.requestAnimationFrame(() => {
      const selectedItemSelector = `[cmdk-item=""][data-value="${window.CSS.escape(selectedCommandId)}"]`;
      const selectedItem =
        commandListRef.current?.querySelector<HTMLElement>(
          selectedItemSelector
        );

      selectedItem?.scrollIntoView({ block: "nearest" });
    });

    return () => {
      window.cancelAnimationFrame(animationFrameId);
    };
  }, [isMenuVisible, selectedCommandId]);

  useEffect(
    () =>
      editor.registerUpdateListener(() => {
        scheduleSlashMenuUpdate();
      }),
    [editor]
  );
  useEffect(
    () => () => {
      if (animationFrameRef.current !== null) {
        window.cancelAnimationFrame(animationFrameRef.current);
      }
      animationFrameRef.current = null;
    },
    []
  );

  const onKeyCommand = useEffectEvent(
    (command: "arrow-down" | "arrow-up" | "enter" | "escape") => {
      switch (command) {
        case "arrow-down": {
          dispatch({
            // Navigate within the filtered list: moving through the full
            // list walks into entries the query hid, and the derived
            // highlight then falls back to the first filtered item —
            // freezing keyboard navigation while searching.
            payload: { commands: filteredCommands, direction: "down" },
            type: "move-selected-command",
          });
          return;
        }
        case "arrow-up": {
          dispatch({
            payload: { commands: filteredCommands, direction: "up" },
            type: "move-selected-command",
          });
          return;
        }
        case "enter": {
          const selectedEntry = filteredEntries[selectedIndex];
          if (selectedEntry) {
            executeEntry(selectedEntry);
          }
          return;
        }
        case "escape": {
          dispatch({ payload: { isOpen: false }, type: "patch" });
          break;
        }
        default: {
          break;
        }
      }
    }
  );

  useEffect(() => {
    // Key handling must match menu visibility exactly: with zero results the
    // popover is hidden, so arrows and enter must reach the editor.
    if (!isMenuVisible) {
      return;
    }

    return mergeRegister(
      editor.registerCommand(
        KEY_ARROW_DOWN_COMMAND,
        (event) => {
          event.preventDefault();
          onKeyCommand("arrow-down");
          return true;
        },
        COMMAND_PRIORITY_HIGH
      ),
      editor.registerCommand(
        KEY_ARROW_UP_COMMAND,
        (event) => {
          event.preventDefault();
          onKeyCommand("arrow-up");
          return true;
        },
        COMMAND_PRIORITY_HIGH
      ),
      editor.registerCommand(
        KEY_ENTER_COMMAND,
        (event) => {
          event?.preventDefault();
          onKeyCommand("enter");
          return true;
        },
        COMMAND_PRIORITY_HIGH
      ),
      editor.registerCommand(
        KEY_ESCAPE_COMMAND,
        () => {
          onKeyCommand("escape");
          return true;
        },
        COMMAND_PRIORITY_HIGH
      )
    );
  }, [editor, isMenuVisible]);

  return (
    <PopoverPrimitive.Root modal={false} open={isMenuVisible}>
      <PopoverPrimitive.Portal>
        <PopoverPrimitive.Positioner
          align="start"
          anchor={anchor}
          className="isolate z-50"
          collisionAvoidance={SLASH_MENU_COLLISION_AVOIDANCE}
          positionMethod="fixed"
          side="bottom"
          sideOffset={4}
        >
          <PopoverPrimitive.Popup
            className={cn(
              "z-50 flex w-72 origin-(--transform-origin) flex-col overflow-hidden rounded-md bg-popover p-0 text-sm text-popover-foreground shadow-md ring-1 ring-foreground/10 outline-hidden duration-100 data-[side=bottom]:slide-in-from-top-2 data-[side=inline-end]:slide-in-from-left-2 data-[side=inline-start]:slide-in-from-right-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 data-open:animate-in data-open:fade-in-0 data-open:zoom-in-95 data-closed:animate-out data-closed:fade-out-0 data-closed:zoom-out-95"
            )}
            data-slot="slash-command-popover"
            finalFocus={false}
            initialFocus={false}
            onFocus={(event) => {
              // `initialFocus: false` makes the focus manager grab focus for
              // the popup, stealing the caret from the editor. Bounce focus
              // back to the editor root so typing continues seamlessly.
              const rootElement = editor.getRootElement();
              if (
                rootElement &&
                event.target !== rootElement &&
                !rootElement.contains(event.target)
              ) {
                rootElement.focus({ preventScroll: true });
              }
            }}
          >
            <Command shouldFilter={false} value={selectedCommandId}>
              <CommandList ref={commandListRef}>
                <CommandGroup heading="Blocks">
                  {filteredEntries.map((entry, index) => {
                    const { command } = entry;
                    return (
                      <CommandItem
                        className={
                          index === selectedIndex
                            ? "bg-accent text-accent-foreground"
                            : ""
                        }
                        key={command.id}
                        onMouseMove={(event) => {
                          const previousPosition =
                            lastPointerPositionRef.current;
                          lastPointerPositionRef.current = {
                            x: event.clientX,
                            y: event.clientY,
                          };

                          if (!previousPosition) {
                            return;
                          }

                          const hasPointerMoved =
                            previousPosition.x !== event.clientX ||
                            previousPosition.y !== event.clientY;

                          if (!hasPointerMoved) {
                            return;
                          }

                          dispatch({
                            payload: { rawSelectedCommandId: command.id },
                            type: "patch",
                          });
                        }}
                        onSelect={() => {
                          // Inline (not `executeEntry`): cmdk invokes this
                          // from user-interaction handlers, outside Effects.
                          dispatch({
                            payload: { isOpen: false },
                            type: "patch",
                          });
                          entry.run(editor);
                        }}
                        value={command.id}
                      >
                        <command.icon className="size-4 shrink-0 text-muted-foreground" />
                        <div className="flex flex-col">
                          <span className="text-sm">{command.label}</span>
                          <span className="text-xs text-muted-foreground">
                            {command.description}
                          </span>
                        </div>
                      </CommandItem>
                    );
                  })}
                </CommandGroup>
                {filteredCommands.length === 0 ? (
                  <CommandEmpty>No results found</CommandEmpty>
                ) : null}
              </CommandList>
            </Command>
          </PopoverPrimitive.Popup>
        </PopoverPrimitive.Positioner>
      </PopoverPrimitive.Portal>
    </PopoverPrimitive.Root>
  );
}

import type { LexicalEditor } from "lexical";
import type { LucideIcon } from "lucide-react";

export type SlashCommandId =
  | "paragraph"
  | "h1"
  | "h2"
  | "h3"
  | "quote"
  | "code"
  | "bullet"
  | "number"
  | "check"
  | "math"
  | "image"
  | "youtube"
  | "excalidraw"
  | "collapsible"
  | "columns"
  | "table"
  | "hr";

export type SlashCommandSelection = SlashCommandId | "";

export interface SlashCommand {
  /** Always show regardless of feature toggles (base block types). */
  alwaysOn?: boolean;
  description: string;
  icon: LucideIcon;
  id: SlashCommandId;
  keywords: string[];
  label: string;
}

/**
 * A slash-menu contribution from a feature descriptor: the rendered menu
 * entry plus what happens when the consumer selects it. Runs receive the
 * editor so features can dispatch their own insert commands or mutate the
 * document directly.
 */
export interface FeatureSlashCommand {
  command: SlashCommand;
  run: (editor: LexicalEditor) => void;
}

export interface SlashMenuPosition {
  left: number;
  top: number;
}

export interface SlashMenuAnchor {
  getBoundingClientRect: () => DOMRect;
  getClientRects: () => DOMRectList;
}

import { $getSelection, $isRangeSelection, $isTextNode } from "lexical";
import type { ElementNode, LexicalEditor } from "lexical";

import type { SlashCommand, SlashCommandSelection } from "./types";

export const SLASH_QUERY_PATTERN = /^\/(?<query>\w*)$/u;

export const filterSlashCommands = (
  commands: readonly SlashCommand[],
  query: string
): SlashCommand[] => {
  if (!query) {
    return commands;
  }

  const normalizedQuery = query.toLowerCase();

  return commands.filter(
    (command) =>
      command.label.toLowerCase().includes(normalizedQuery) ||
      command.keywords.some((keyword) => keyword.includes(normalizedQuery))
  );
};

export const getFirstCommandId = (
  commands: readonly SlashCommand[]
): SlashCommandSelection => commands[0]?.id ?? "";

export const getSelectedCommandIndex = (
  commands: readonly SlashCommand[],
  selectedCommandId: SlashCommandSelection
): number => commands.findIndex((command) => command.id === selectedCommandId);

export const getNeighborCommandId = (
  commands: readonly SlashCommand[],
  selectedCommandId: SlashCommandSelection,
  direction: "down" | "up"
): SlashCommandSelection => {
  const currentIndex = getSelectedCommandIndex(commands, selectedCommandId);

  // A stale selection (the query filtered it out) acts as if it sat at the
  // effective highlight edge, so the very first arrow key press moves off it
  // instead of re-syncing to the first item.
  if (currentIndex < 0) {
    return direction === "down"
      ? (commands.at(1)?.id ?? getFirstCommandId(commands))
      : (commands.at(-1)?.id ?? getFirstCommandId(commands));
  }

  const nextIndex =
    direction === "down"
      ? Math.min(currentIndex + 1, commands.length - 1)
      : Math.max(currentIndex - 1, 0);

  return commands[nextIndex]?.id ?? selectedCommandId;
};

export const hasSelectedCommand = (
  commands: readonly SlashCommand[],
  selectedCommandId: SlashCommandSelection
): boolean => commands.some((command) => command.id === selectedCommandId);

export const getSlashQueryMatch = (textUpToCursor: string): string | null => {
  const match = textUpToCursor.match(SLASH_QUERY_PATTERN);

  return match?.groups?.query ?? null;
};

/**
 * Runs a block-level replacement against the current selection: clears the
 * text content of the selected text node and hands the enclosing top-level
 * element to the callback. Mirrors the flow the slash menu has always used
 * for direct executors.
 */
export const replaceCurrentBlock = (
  editor: LexicalEditor,
  replace: (element: ElementNode) => void
): void => {
  editor.update(() => {
    const selection = $getSelection();

    if (!$isRangeSelection(selection)) {
      return;
    }

    const node = selection.anchor.getNode();

    if (!$isTextNode(node)) {
      return;
    }

    node.setTextContent("");
    replace(node.getTopLevelElementOrThrow());
  });
};

