import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useMemo,
  useState,
} from "react";

import {
  applyThemeToDOM,
  getSystemTheme,
  readStoredTheme,
  STORAGE_KEY,
  ThemeContext,
} from "./theme-context";
import type { Theme, ThemeProviderState } from "./theme-context";

export function ThemeProvider({ children }: { children: React.ReactNode }) {
  const [theme, setTheme] = useState<Theme>(readStoredTheme);
  const [systemTheme, setSystemTheme] = useState<"light" | "dark">(
    getSystemTheme
  );
  const resolvedTheme = theme === "system" ? systemTheme : theme;

  const updateTheme = useCallback((next: Theme) => {
    localStorage.setItem(STORAGE_KEY, next);
    setTheme(next);
  }, []);

  // Layout effect so the .dark class flips in the same commit as consumers
  // (e.g. Shiki inline colors) — avoids a painted frame with mismatched
  // tokens, which shows up as a flash on theme-styled elements.
  useLayoutEffect(() => {
    applyThemeToDOM(resolvedTheme);
  }, [resolvedTheme]);

  useEffect(() => {
    if (theme !== "system") {
      return;
    }

    const mediaQuery = window.matchMedia("(prefers-color-scheme: dark)");

    const handleChange = () => {
      setSystemTheme(getSystemTheme());
    };

    mediaQuery.addEventListener("change", handleChange);
    return () => {
      mediaQuery.removeEventListener("change", handleChange);
    };
  }, [theme]);

  const value = useMemo<ThemeProviderState>(
    () => ({ resolvedTheme, setTheme: updateTheme, theme }),
    [resolvedTheme, theme, updateTheme]
  );

  return (
    <ThemeContext.Provider value={value}>{children}</ThemeContext.Provider>
  );
}

import { createContext, useContext } from "react";

export type Theme = "light" | "dark" | "system";

export interface ThemeProviderState {
  resolvedTheme: "light" | "dark";
  setTheme: (theme: Theme) => void;
  theme: Theme;
}

export const STORAGE_KEY = "pytah-theme";

export const ThemeContext = createContext<ThemeProviderState | undefined>(
  undefined
);

export function getSystemTheme(): "light" | "dark" {
  if (typeof window === "undefined") {
    return "light";
  }
  return window.matchMedia("(prefers-color-scheme: dark)").matches
    ? "dark"
    : "light";
}

export function readStoredTheme(): Theme {
  if (typeof window === "undefined") {
    return "system";
  }

  const stored = localStorage.getItem(STORAGE_KEY);
  if (stored === "light" || stored === "dark" || stored === "system") {
    return stored;
  }
  return "system";
}

export function disableTransitions(): () => void {
  const css = document.createElement("style");
  css.append(
    document.createTextNode(
      "*,*::before,*::after{-webkit-transition:none!important;-moz-transition:none!important;-o-transition:none!important;-ms-transition:none!important;transition:none!important;-webkit-animation-play-state:paused!important;animation-play-state:paused!important}"
    )
  );
  document.head.append(css);

  let removed = false;

  return () => {
    // Force synchronous style/layout calculation so the theme swap applies
    // while transitions are disabled and running animations are paused
    window.getComputedStyle(document.body);

    // Keep the suppression alive until the swapped frame has actually been
    // painted: a bare 1ms timeout can fire before that frame is committed,
    // letting elements with transition-* classes visibly interpolate.
    requestAnimationFrame(() => {
      requestAnimationFrame(() => {
        if (removed) {
          return;
        }
        removed = true;
        css.remove();
      });
    });
    setTimeout(() => {
      if (removed) {
        return;
      }
      removed = true;
      css.remove();
    }, 100);
  };
}

export function applyThemeToDOM(resolved: "light" | "dark"): void {
  if (typeof document === "undefined") {
    return;
  }

  const root = document.documentElement;
  const isDark = root.classList.contains("dark");
  const shouldBeDark = resolved === "dark";

  if (isDark === shouldBeDark) {
    return;
  }

  const restoreTransitions = disableTransitions();

  root.classList.toggle("dark", shouldBeDark);

  restoreTransitions();
}

export function useTheme(): ThemeProviderState {
  const context = useContext(ThemeContext);

  if (!context) {
    throw new Error("useTheme must be used within a ThemeProvider");
  }

  return context;
}
